-- Griechenland
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Griechenland$t$, $t$griechenland$t$, $t$Griechenland$t$, $t$Südosteuropa$t$, $t$Europa$t$, $t$/images/destinations/griechenland-hero.jpg$t$, $t$Wiege der abendländischen Kultur mit der Akropolis, traumhaften Inseln wie Santorin und Kreta, türkisem Meer, antiken Stätten und herzlicher Gastfreundschaft.$t$, $t$Griechenland verbindet jahrtausendealte Geschichte mit mediterranem Lebensgefühl und einigen der schönsten Inseln Europas. In der Hauptstadt Athen thront die Akropolis mit dem Parthenon über der Stadt und erzählt von der Wiege der westlichen Zivilisation. Doch das eigentliche Sehnsuchtsbild Griechenlands sind seine Inseln: das vulkanische Santorin mit den weiß getünchten Häusern über der Caldera, das glamouröse Mykonos, das vielseitige Kreta mit Palast von Knossos und Samaria-Schlucht, das mittelalterliche Rhodos und das grüne Korfu. Auf dem Festland beeindrucken die spektakulär gelegenen Meteora-Klöster, das antike Orakel von Delphi und die Peloponnes mit Mykene und dem malerischen Nafplio. Dazu kommen türkisfarbene Buchten, herzliche Gastfreundschaft und eine gesunde, schmackhafte Küche. Ob Inselhüpfen, Strandurlaub, Kulturreise oder Segeltörn – Griechenland ist von Deutschland aus gut erreichbar und ein Klassiker für unvergessliche Sommerurlaube.$t$, $t$Griechenland ist ein mediterranes Reiseland mit der Akropolis in Athen, traumhaften Inseln wie Santorin, Mykonos, Kreta und Rhodos, antiken Stätten wie Delphi und den Meteora-Klöstern sowie türkisem Meer. Es eignet sich ideal für Inselhüpfen, Strandurlaub, Kultur- und Rundreisen und ist von Deutschland aus gut erreichbar.$t$, $t$Mai bis Juni sowie September und Oktober für angenehme Temperaturen und weniger Andrang; der Hochsommer ist heiß und voll, die Inseln sind etwa von Mai bis Oktober bereisbar.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Inselhüpfen$t$,$t$Kulturreise$t$,$t$Rundreise$t$,$t$Familien$t$,$t$Kulinarik$t$,$t$Segeln$t$]::text[], $j${"currency":"Euro (EUR)","language":"Griechisch","flightTime":"ca. 2,5 bis 3 Stunden ab Deutschland (Athen)","timezone":"OEZ (UTC+2), eine Stunde vor MEZ","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Athen – die Akropolis mit dem Parthenon und die antike Altstadt","Santorin – weiße Häuser über der Caldera und berühmte Sonnenuntergänge in Oia","Mykonos – Windmühlen, weiße Gassen und lebendiges Nachtleben","Kreta – Palast von Knossos, Strände und die Samaria-Schlucht","Rhodos – mittelalterliche Altstadt und das malerische Lindos","Meteora – spektakulär auf Felsen thronende Klöster, UNESCO-Welterbe","Delphi – das antike Orakel in beeindruckender Berglage","Peloponnes – Mykene, antikes Epidauros und das charmante Nafplio"]$j$::jsonb, $j$["Beim Inselhüpfen lohnt es sich, die Fährverbindungen in der Hochsaison vorab zu buchen, da beliebte Routen schnell ausgebucht sind.","Der berühmte Sonnenuntergang in Oia auf Santorin ist sehr überlaufen – früh kommen oder einen ruhigeren Aussichtspunkt im Ort suchen.","Statt der bekannten Hotspots Santorin und Mykonos sind Inseln wie Naxos, Milos oder Paros oft ruhiger, authentischer und günstiger.","In einer echten Taverne bestellt man am besten mehrere Meze zum Teilen – das ist gesellig und ein guter Querschnitt der griechischen Küche."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Griechenland?","answer":"Am angenehmsten sind Mai bis Juni sowie September und Oktober mit warmem, aber nicht zu heißem Wetter und weniger Andrang. Der Hochsommer ist sehr heiß und voll; die Inseln sind etwa von Mai bis Oktober bereisbar."},{"question":"Welche Währung gilt in Griechenland?","answer":"In Griechenland zahlt man mit dem Euro (EUR). Kartenzahlung ist verbreitet, auf kleineren Inseln und in Tavernen ist jedoch etwas Bargeld nützlich."},{"question":"Brauche ich ein Visum für Griechenland?","answer":"Nein. Griechenland ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Wie funktioniert Inselhüpfen in Griechenland?","answer":"Die Inseln sind über ein dichtes Netz an Fähren und Schnellbooten verbunden, ergänzt durch Inlandsflüge. Beliebt sind Routen innerhalb der Kykladen. In der Hochsaison sollte man Tickets im Voraus buchen und Puffer einplanen."},{"question":"Lohnt sich ein Mietwagen in Griechenland?","answer":"Auf größeren Inseln und auf dem Festland ist ein Mietwagen sehr praktisch, um abgelegene Strände, Dörfer und antike Stätten zu erreichen. In Athen ist er wegen des guten Nahverkehrs und des Verkehrs eher nicht nötig."},{"question":"Welche griechische Insel passt zu mir?","answer":"Santorin steht für Romantik und Aussicht, Mykonos für Nachtleben, Kreta und Rhodos für Vielfalt und Geschichte, Korfu für Grün, und Naxos, Paros oder Milos für ruhigere, authentische Erlebnisse."},{"question":"Ist Griechenland für einen Familienurlaub geeignet?","answer":"Ja, Griechenland ist sehr familienfreundlich. Flache Strände, warmes Meer, kinderfreundliche Tavernen und die herzliche Gastfreundschaft machen es zu einem beliebten Ziel für Familien."},{"question":"Welche Spezialitäten sollte man in Griechenland probieren?","answer":"Typisch sind Souvlaki und Gyros, Moussaka, griechischer Salat, Tzatziki, frischer Fisch und verschiedene Meze. Dazu passen Ouzo, Wein und zum Abschluss griechischer Joghurt mit Honig."},{"question":"Ist Griechenland sicher für Reisende?","answer":"Ja, Griechenland gilt als sicheres Reiseland mit gastfreundlichen Menschen. In Athen und an touristischen Orten sollte man wie überall auf Taschendiebe achten."},{"question":"Spricht man in Griechenland Englisch?","answer":"In touristischen Regionen und auf den Inseln kommt man mit Englisch sehr gut zurecht. Ein paar griechische Höflichkeitsfloskeln werden jedoch gern gesehen und erleichtern den Kontakt."},{"question":"Wie viele Tage sollte man für Griechenland einplanen?","answer":"Für eine Insel oder Athen reichen einige Tage. Für eine Kombination aus Athen und ein bis zwei Inseln oder eine Rundreise auf dem Festland sollte man 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Griechenland Urlaub: Inseln, Akropolis, Tipps & beste Reisezeit$t$, $t$Dein Griechenland-Urlaub: die Akropolis in Athen, Inseln wie Santorin, Mykonos und Kreta, antike Stätten und türkises Meer. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Griechenland Urlaub buchen, Flug und Hotel Kreta oder Rhodos, Mietwagen Griechenland vergleichen, Inselhüpfen Kykladen, Strandurlaub Griechenland, Städtereise Athen$t$, true, $j$["italien","kroatien","tuerkei"]$j$::jsonb, ARRAY[$t$Griechenland$t$,$t$Athen$t$,$t$Akropolis$t$,$t$Parthenon$t$,$t$Santorin$t$,$t$Oia$t$,$t$Mykonos$t$,$t$Kreta$t$,$t$Knossos$t$,$t$Rhodos$t$,$t$Lindos$t$,$t$Meteora$t$,$t$Delphi$t$,$t$Peloponnes$t$,$t$Kykladen$t$,$t$Souvlaki$t$]::text[], $t$Griechenland ist ein mediterranes Reiseland und die Wiege der abendländischen Kultur, bekannt für die Akropolis in Athen, traumhafte Inseln wie Santorin, Mykonos, Kreta und Rhodos, antike Stätten wie Delphi und die Meteora-Klöster sowie türkisfarbenes Meer. Es eignet sich ideal für Inselhüpfen, Strandurlaub, Kultur- und Rundreisen und ist von Deutschland aus gut erreichbar. Die beste Reisezeit liegt im späten Frühjahr und Frühherbst.$t$, $t$Griechenland ist ein mediterranes Reiseland mit der Akropolis in Athen, Trauminseln wie Santorin, Mykonos und Kreta sowie antiken Stätten und türkisem Meer.$t$, $t$https://www.apearound.de/reiseziele/griechenland$t$, $t$/images/destinations/griechenland.jpg$t$, $t$/images/destinations/griechenland.jpg$t$, $t$Griechenland Urlaub: Inseln, Akropolis, Tipps & beste Reisezeit$t$, $t$Dein Griechenland-Urlaub: die Akropolis in Athen, Inseln wie Santorin, Mykonos und Kreta, antike Stätten und türkises Meer. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Griechenland Urlaub: Inseln, Akropolis, Tipps & beste Reisezeit$t$, $t$Dein Griechenland-Urlaub: die Akropolis in Athen, Inseln wie Santorin, Mykonos und Kreta, antike Stätten und türkises Meer. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Grönland
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Grönland$t$, $t$groenland$t$, $t$Grönland (zum Königreich Dänemark)$t$, $t$Arktis (Nordatlantik)$t$, $t$Nordamerika$t$, $t$/images/destinations/groenland-hero.jpg$t$, $t$Die größte Insel der Erde als arktisches Abenteuer mit gewaltigen Eisbergen, Gletschern, dem Inlandeis, Nordlichtern, Walen und der Kultur der Inuit.$t$, $t$Grönland ist die größte Insel der Erde und eines der letzten großen Abenteuer unseres Planeten – ein arktisches Reich aus Eis, Stille und überwältigender Weite. Der größte Teil der Insel wird vom mächtigen Inlandeis bedeckt, der nach der Antarktis zweitgrößten Eismasse der Welt. Das absolute Highlight ist der Ilulissat-Eisfjord, UNESCO-Welterbe, wo haushohe Eisberge vom produktivsten Gletscher der Nordhalbkugel ins Meer treiben. In der bunten Hauptstadt Nuuk treffen Inuit-Kultur und moderne Architektur aufeinander. Im Sommer locken die Mitternachtssonne, Bootstouren zwischen Eisbergen, Wal- und Robbenbeobachtung sowie Wanderungen etwa auf dem Arctic Circle Trail; im Winter tanzen die Nordlichter über verschneiten Siedlungen, und Hundeschlittenfahrten gehören zu den unvergesslichen Erlebnissen. Eine Besonderheit: Zwischen den Orten gibt es keine Straßen – gereist wird per Flugzeug, Helikopter oder Boot. Grönland ist abgelegen, teuer und wetterabhängig, belohnt aber mit einer Natur, die ihresgleichen sucht. Ideal für Natur-, Abenteuer- und Expeditionsreisen sowie Kreuzfahrten.$t$, $t$Grönland ist die größte Insel der Erde, ein arktisches Abenteuer mit dem UNESCO-Eisfjord von Ilulissat, gewaltigen Eisbergen, dem Inlandeis, Nordlichtern im Winter, der Mitternachtssonne im Sommer und der Kultur der Inuit. Zwischen den Orten gibt es keine Straßen, gereist wird per Flug, Helikopter oder Boot. Es eignet sich ideal für Natur-, Abenteuer- und Expeditionsreisen, ist aber abgelegen und teuer.$t$, $t$Juni bis September für eisfreiere Küsten, Wandern, Wal-Beobachtung, Bootstouren und die Mitternachtssonne; Februar bis April für Nordlichter, Schnee und Hundeschlittenfahrten.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Naturreise$t$,$t$Abenteuer$t$,$t$Expedition$t$,$t$Kreuzfahrt$t$,$t$Nordlichter$t$,$t$Wandern$t$,$t$Tierbeobachtung$t$]::text[], $j${"currency":"Dänische Krone (DKK)","language":"Grönländisch (Kalaallisut) und Dänisch; Englisch in touristischen Kontexten","flightTime":"Keine Direktflüge aus Deutschland; Anreise über Kopenhagen oder Island nach Nuuk, Ilulissat oder Kangerlussuaq (ab Kopenhagen rund 4,5 Stunden plus Zubringer). Seit Ende 2024 erleichtert ein neuer internationaler Flughafen in Nuuk die Anreise","timezone":"Mehrere Zeitzonen; Westgrönland/Nuuk UTC−2 (im Sommer UTC−1), rund drei Stunden hinter MEZ","visa":"Kein Visum für EU-Bürger nötig, aber ein Reisepass ist erforderlich, da Grönland nicht zum Schengen-Raum gehört (ein Schengen-Visum gilt hier nicht)","bestMonths":"Juni bis September"}$j$::jsonb, $j$["Ilulissat-Eisfjord – haushohe Eisberge, UNESCO-Welterbe","Inlandeis – die nach der Antarktis zweitgrößte Eismasse der Erde","Nuuk – bunte Hauptstadt mit Inuit-Kultur und moderner Architektur","Disko-Bucht – Eisberge, Wale und die Insel Disko","Nordlichter – über verschneiten Siedlungen im Winter","Mitternachtssonne – taghelle Nächte im Sommer","Wal- und Robbenbeobachtung sowie Hundeschlittenfahrten","Arctic Circle Trail – legendäre Fernwanderung durch die Tundra"]$j$::jsonb, $j$["Zwischen den Orten gibt es keine Straßen – Reisen erfolgen per Flugzeug, Helikopter oder Boot; ein Mietwagen ist daher nicht sinnvoll.","Das Wetter kann Flüge und Bootstouren kurzfristig verzögern – immer großzügige Pufferzeiten einplanen, besonders bei An- und Abreise.","Der Ilulissat-Eisfjord ist ein Muss; eine Bootstour zwischen den Eisbergen oder eine Mitternachtssonnen-Fahrt gehört zu den eindrucksvollsten Erlebnissen.","Grönland ist abgelegen und teuer; eine Expeditionskreuzfahrt ist eine bequeme Möglichkeit, mehrere Küstenorte ohne komplizierte Einzelflüge zu verbinden."]$j$::jsonb, $j$[{"question":"Brauche ich für Grönland ein Visum?","answer":"EU-Bürger benötigen für touristische Aufenthalte kein Visum, jedoch einen gültigen Reisepass. Wichtig: Grönland gehört zwar zum Königreich Dänemark, aber nicht zum Schengen-Raum, daher reicht der Personalausweis nicht, und ein Schengen-Visum gilt hier nicht."},{"question":"Wann ist die beste Reisezeit für Grönland?","answer":"Der Sommer von Juni bis September ist ideal für Wandern, Bootstouren zwischen Eisbergen, Walbeobachtung und die Mitternachtssonne. Für Nordlichter, Schnee und Hundeschlittenfahrten reist man im Winter, etwa von Februar bis April."},{"question":"Wie reist man nach Grönland an?","answer":"Es gibt keine Direktflüge aus Deutschland. Üblich ist die Anreise über Kopenhagen oder Island nach Nuuk, Ilulissat oder Kangerlussuaq. Seit Ende 2024 erleichtert ein neuer internationaler Flughafen in Nuuk die Anreise mit größeren Maschinen."},{"question":"Wie reist man innerhalb Grönlands?","answer":"Eine Besonderheit Grönlands: Zwischen den Städten und Dörfern gibt es keine Straßen. Gereist wird ausschließlich mit dem Flugzeug, dem Helikopter oder per Boot, was Reisen aufwendig und wetterabhängig macht."},{"question":"Welche Währung gilt in Grönland?","answer":"Gezahlt wird mit der Dänischen Krone (DKK). Kartenzahlung ist in Städten verbreitet, doch in abgelegenen Orten ist etwas Bargeld ratsam. Die Preise sind generell hoch."},{"question":"Ist Grönland ein teures Reiseland?","answer":"Ja, Grönland ist wegen der abgelegenen Lage und der aufwendigen Logistik teuer. Flüge zwischen den Orten, Unterkünfte und Touren kosten deutlich mehr als in Mitteleuropa. Eine gute Vorausplanung und ein realistisches Budget sind wichtig."},{"question":"Was kann man am Ilulissat-Eisfjord erleben?","answer":"Der Ilulissat-Eisfjord ist UNESCO-Welterbe und berühmt für seine gewaltigen Eisberge, die vom Sermeq-Kujalleq-Gletscher stammen. Man erlebt ihn auf Wanderwegen am Ufer oder bei Bootstouren, die nah an die schwimmenden Eisriesen heranführen."},{"question":"Sieht man in Grönland Nordlichter und die Mitternachtssonne?","answer":"Ja. Die Nordlichter zeigen sich in den dunklen Monaten, besonders von Herbst bis Frühjahr. Im Hochsommer geht im Norden die Sonne wochenlang nicht unter – die Mitternachtssonne sorgt dann für taghelle Nächte."},{"question":"Welche Sprache spricht man in Grönland?","answer":"Amtssprache ist Grönländisch (Kalaallisut), zudem wird Dänisch gesprochen. In touristischen Kontexten kommt man oft auch mit Englisch zurecht, in abgelegenen Dörfern sind die Kenntnisse jedoch begrenzt."},{"question":"Wie viele Tage sollte man für Grönland einplanen?","answer":"Wegen der aufwendigen Anreise und der wetterabhängigen Verbindungen lohnen sich mindestens 1 bis 2 Wochen. So bleibt genügend Puffer für mögliche Verzögerungen und Zeit, mehrere Regionen oder eine Kreuzfahrt zu erleben."}]$j$::jsonb, $t$Grönland Reisen: Eisberge, Nordlichter & beste Reisezeit$t$, $t$Deine Grönland-Reise: der UNESCO-Eisfjord von Ilulissat, gewaltige Eisberge, das Inlandeis, Nordlichter und die Kultur der Inuit. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$Grönland Reise buchen, Flug nach Nuuk oder Ilulissat, Grönland Kreuzfahrt, Expeditionsreise Grönland, Nordlichter Grönland, Ilulissat Eisfjord Tour$t$, false, $j$["island","norwegen","daenemark"]$j$::jsonb, ARRAY[$t$Grönland$t$,$t$Arktis$t$,$t$Königreich Dänemark$t$,$t$Ilulissat$t$,$t$Ilulissat-Eisfjord$t$,$t$Inlandeis$t$,$t$Nuuk$t$,$t$Disko-Bucht$t$,$t$Kangerlussuaq$t$,$t$Nordlichter$t$,$t$Mitternachtssonne$t$,$t$Inuit$t$,$t$Arctic Circle Trail$t$,$t$Sermeq Kujalleq$t$,$t$Dänische Krone$t$]::text[], $t$Grönland ist die größte Insel der Erde und ein arktisches Abenteuer mit dem UNESCO-Eisfjord von Ilulissat, gewaltigen Eisbergen, dem mächtigen Inlandeis, Nordlichtern im Winter, der Mitternachtssonne im Sommer und der Kultur der Inuit. Eine Besonderheit: Zwischen den Orten gibt es keine Straßen, gereist wird per Flugzeug, Helikopter oder Boot. Das abgelegene und teure Ziel eignet sich ideal für Natur-, Abenteuer- und Expeditionsreisen sowie Kreuzfahrten, am besten von Juni bis September; für die Einreise ist ein Reisepass nötig, da Grönland nicht zum Schengen-Raum gehört.$t$, $t$Grönland ist die größte Insel der Erde, ein arktisches Abenteuer mit Eisbergen, dem Ilulissat-Eisfjord, Nordlichtern und Inuit-Kultur – ganz ohne Straßen zwischen den Orten.$t$, $t$https://www.apearound.de/reiseziele/groenland$t$, $t$/images/destinations/groenland.jpg$t$, $t$/images/destinations/groenland.jpg$t$, $t$Grönland Reisen: Eisberge, Nordlichter & beste Reisezeit$t$, $t$Deine Grönland-Reise: der UNESCO-Eisfjord von Ilulissat, gewaltige Eisberge, das Inlandeis, Nordlichter und die Kultur der Inuit. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$Grönland Reisen: Eisberge, Nordlichter & beste Reisezeit$t$, $t$Deine Grönland-Reise: der UNESCO-Eisfjord von Ilulissat, gewaltige Eisberge, das Inlandeis, Nordlichter und die Kultur der Inuit. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Hamburg
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Hamburg$t$, $t$hamburg$t$, $t$Deutschland$t$, $t$Norddeutschland$t$, $t$Europa$t$, $t$/images/destinations/hamburg-hero.jpg$t$, $t$Das maritime Tor zur Welt mit der spektakulären Elbphilharmonie, der UNESCO-Speicherstadt, dem großen Hafen, der Reeperbahn und der idyllischen Alster.$t$, $t$Hamburg ist Deutschlands maritime Metropole und vereint norddeutsches Understatement mit weltstädtischem Flair. Das Wahrzeichen der Stadt ist die Elbphilharmonie, deren geschwungenes Glasdach über dem Hafen thront und deren Plaza einen herrlichen Rundumblick bietet. Direkt daneben erstreckt sich die UNESCO-Welterbe-Speicherstadt, der weltgrößte zusammenhängende Lagerhauskomplex mit ihren roten Backsteinfassaden und Fleeten, die nahtlos in die moderne HafenCity übergeht. Der Hamburger Hafen lädt zu Rundfahrten und Spaziergängen an den Landungsbrücken ein, während die Reeperbahn im Stadtteil St. Pauli für ihr legendäres Nachtleben bekannt ist. Rund um die Binnen- und Außenalster genießt man bei einer Bootsfahrt oder einem Spaziergang das entspannte Lebensgefühl der Stadt. Familien begeistert das Miniatur Wunderland, die größte Modelleisenbahn der Welt, und am frühen Sonntagmorgen lockt der traditionsreiche Fischmarkt. Als Musical-Hauptstadt Deutschlands und mit ihrer lebendigen Kulinarik ist Hamburg ein ideales Ziel für einen Städtetrip übers Wochenende.$t$, $t$Hamburg ist Deutschlands maritime Metropole mit der spektakulären Elbphilharmonie, der UNESCO-Speicherstadt und HafenCity, dem großen Hafen, der Reeperbahn und der idyllischen Alster. Als Musical-Hauptstadt und mit lebendiger Kulinarik eignet sie sich ideal für einen Städtetrip übers Wochenende und ist innerdeutsch bequem erreichbar.$t$, $t$Mai bis September mit mildem Wetter ist ideal für Hafen, Alster und Außengastronomie; im Advent verzaubern stimmungsvolle Weihnachtsmärkte die Stadt.$t$, $t$2 bis 3 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Wochenendtrip$t$,$t$Kulinarik$t$,$t$Familien$t$,$t$Shopping$t$]::text[], $j${"currency":"Euro (EUR)","language":"Deutsch","flightTime":"Innerdeutsches Ziel; bequem per ICE (z. B. aus Berlin rund 1,5 bis 2 Stunden) oder mit dem Auto. Der Flughafen Hamburg liegt zentrumsnah","timezone":"MEZ (UTC+1)","visa":"Nicht erforderlich (innerdeutsch bzw. für EU-Bürger im Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Elbphilharmonie – Wahrzeichen der Stadt mit Aussichtsplaza über dem Hafen","Speicherstadt – weltgrößter Lagerhauskomplex, UNESCO-Welterbe","Hamburger Hafen und Landungsbrücken – Hafenrundfahrten und maritimes Flair","Reeperbahn und St. Pauli – legendäres Vergnügungs- und Nachtleben","Binnen- und Außenalster – Bootsfahrten und Spaziergänge im Grünen","Miniatur Wunderland – größte Modelleisenbahnanlage der Welt","Fischmarkt – traditionsreiches Markttreiben am frühen Sonntagmorgen","HafenCity – modernes Stadtviertel rund um die Elbphilharmonie"]$j$::jsonb, $j$["Die Aussichtsplaza der Elbphilharmonie bietet einen tollen Rundumblick über Hafen und Stadt – das Plaza-Ticket sollte man vorab online sichern.","Eine günstige „Hafenrundfahrt“ gelingt mit der HVV-Fährlinie 62 ab den Landungsbrücken – mit normalem Nahverkehrsticket statt teurer Touristentour.","Der Fischmarkt in Altona findet sonntags am frühen Morgen statt – ein Erlebnis mit Marktschreiern, Livemusik und Hafenkulisse.","Unbedingt ein Franzbrötchen probieren, das süße Zimtgebäck ist eine echte Hamburger Spezialität; für den Nahverkehr lohnt sich ein HVV-Tagesticket."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Hamburg?","answer":"Am angenehmsten ist es von Mai bis September, wenn man Hafen, Alster und Außengastronomie genießen kann. Die Stadt ist aber ganzjährig reizvoll, und im Advent sorgen schöne Weihnachtsmärkte für besonderes Flair. Regenfeste Kleidung ist immer ratsam."},{"question":"Wie reist man am besten nach Hamburg an?","answer":"Aus den meisten Teilen Deutschlands ist Hamburg bequem per ICE erreichbar, etwa in rund 1,5 bis 2 Stunden aus Berlin. Auch die Anreise mit dem Auto ist gut möglich, und der Flughafen Hamburg liegt nah am Zentrum."},{"question":"Braucht man in Hamburg ein Auto?","answer":"Nein, Hamburg verfügt über einen sehr guten öffentlichen Nahverkehr mit U-Bahn, S-Bahn, Bussen und Fähren (HVV). Die Innenstadt lässt sich gut zu Fuß erkunden, ein Auto ist eher hinderlich."},{"question":"Kann man die Elbphilharmonie besichtigen?","answer":"Ja. Die Aussichtsplaza ist mit einem kostengünstigen Ticket zugänglich und bietet einen herrlichen Blick über den Hafen. Für Konzerte im Großen Saal sollte man Karten frühzeitig buchen, da sie sehr begehrt sind."},{"question":"Was ist die Speicherstadt?","answer":"Die Speicherstadt ist der weltgrößte zusammenhängende Lagerhauskomplex und gehört zum UNESCO-Welterbe. Mit ihren roten Backsteinbauten und Wasserkanälen ist sie besonders abends stimmungsvoll und beherbergt unter anderem das Miniatur Wunderland."},{"question":"Lohnt sich das Miniatur Wunderland?","answer":"Ja, vor allem für Familien und Technikbegeisterte. Es ist die größte Modelleisenbahn der Welt und äußerst detailreich. Wegen des großen Andrangs sollte man Tickets unbedingt vorab online buchen und ein Zeitfenster reservieren."},{"question":"Was hat es mit dem Fischmarkt auf sich?","answer":"Der Hamburger Fischmarkt in Altona findet jeden Sonntag am frühen Morgen statt. Neben Fisch, Obst und Blumen sorgen Marktschreier und Livemusik in der historischen Fischauktionshalle für eine einzigartige Atmosphäre."},{"question":"Ist Hamburg für einen Familienurlaub geeignet?","answer":"Ja, Hamburg ist sehr familienfreundlich. Das Miniatur Wunderland, Hafenrundfahrten, der Tierpark Hagenbeck, Parks wie Planten un Blomen und kindgerechte Museen bieten viel Abwechslung."},{"question":"Ist Hamburg für Musicals bekannt?","answer":"Ja, Hamburg gilt als Musical-Hauptstadt Deutschlands. Im Hafen werden bekannte Produktionen gezeigt, die man über eigene Fähren erreicht. Musical-Tickets und Pakete sollte man je nach Show frühzeitig buchen."},{"question":"Wie viele Tage sollte man für Hamburg einplanen?","answer":"Für die wichtigsten Highlights eignet sich ein Wochenende von 2 bis 3 Tagen. Wer Museen, Musicals und Ausflüge ins Umland verbinden möchte, kann auch problemlos länger bleiben."}]$j$::jsonb, $t$Hamburg Städtereise: Elbphilharmonie, Hafen & beste Reisezeit$t$, $t$Dein Hamburg-Trip: die Elbphilharmonie, die UNESCO-Speicherstadt, der Hafen, die Reeperbahn und die Alster. Beste Reisezeit, Anreise, Highlights und praktische Tipps im Überblick.$t$, $t$Hamburg Städtereise buchen, Hotel Hamburg, Hamburg Wochenende, Elbphilharmonie Tickets, Hafenrundfahrt Hamburg, Musical Hamburg, Miniatur Wunderland Tickets$t$, false, $j$["berlin","bremen","duesseldorf"]$j$::jsonb, ARRAY[$t$Hamburg$t$,$t$Elbphilharmonie$t$,$t$Speicherstadt$t$,$t$HafenCity$t$,$t$Hamburger Hafen$t$,$t$Landungsbrücken$t$,$t$Reeperbahn$t$,$t$St. Pauli$t$,$t$Alster$t$,$t$Binnenalster$t$,$t$Außenalster$t$,$t$Miniatur Wunderland$t$,$t$Fischmarkt$t$,$t$Michel$t$,$t$Planten un Blomen$t$,$t$HVV$t$]::text[], $t$Hamburg ist Deutschlands maritime Metropole mit der spektakulären Elbphilharmonie, der zum UNESCO-Welterbe zählenden Speicherstadt, dem großen Hafen mit den Landungsbrücken, der berühmten Reeperbahn und der idyllischen Alster. Als Musical-Hauptstadt Deutschlands und mit Attraktionen wie dem Miniatur Wunderland und dem Fischmarkt eignet sie sich ideal für einen Städtetrip übers Wochenende. Die beste Reisezeit liegt zwischen Mai und September, und innerdeutsch ist die Stadt per ICE bequem erreichbar.$t$, $t$Hamburg ist Deutschlands maritime Metropole mit Elbphilharmonie, UNESCO-Speicherstadt, großem Hafen, Reeperbahn und Alster – ideal für einen Städtetrip übers Wochenende.$t$, $t$https://www.apearound.de/reiseziele/hamburg$t$, $t$/images/destinations/hamburg.jpg$t$, $t$/images/destinations/hamburg.jpg$t$, $t$Hamburg Städtereise: Elbphilharmonie, Hafen & beste Reisezeit$t$, $t$Dein Hamburg-Trip: die Elbphilharmonie, die UNESCO-Speicherstadt, der Hafen, die Reeperbahn und die Alster. Beste Reisezeit, Anreise, Highlights und praktische Tipps im Überblick.$t$, $t$Hamburg Städtereise: Elbphilharmonie, Hafen & beste Reisezeit$t$, $t$Dein Hamburg-Trip: die Elbphilharmonie, die UNESCO-Speicherstadt, der Hafen, die Reeperbahn und die Alster. Beste Reisezeit, Anreise, Highlights und praktische Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Hawaii
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Hawaii$t$, $t$hawaii$t$, $t$Vereinigte Staaten (USA)$t$, $t$Hawaii (Pazifik)$t$, $t$Ozeanien$t$, $t$/images/destinations/hawaii-hero.jpg$t$, $t$Tropisches Inselparadies im Pazifik mit Traumstränden, aktiven Vulkanen, üppigem Regenwald, Surfwellen, Walen und der herzlichen Aloha-Kultur.$t$, $t$Hawaii ist der Inbegriff des tropischen Paradieses und zugleich der einzige US-Bundesstaat mitten im Pazifik. Der Archipel besteht aus mehreren Hauptinseln, die jeweils ihren eigenen Charakter haben. Oʻahu ist mit der Hauptstadt Honolulu, dem berühmten Waikiki Beach und der Gedenkstätte Pearl Harbor das pulsierende Zentrum, während die Nordküste im Winter zum Mekka der Surfer wird. Maui begeistert mit der kurvenreichen Road to Hana und dem Sonnenaufgang über dem Vulkan Haleakalā. Auf Big Island, der jüngsten Insel, kann man im Volcanoes-Nationalpark die aktiven Vulkane Kīlauea und Mauna Loa erleben. Das „Garteninsel“ genannte Kauaʻi verzaubert mit der dramatischen Nā Pali Coast und dem farbenprächtigen Waimea Canyon. Dazu kommen exzellente Schnorchel- und Tauchreviere, die Beobachtung von Buckelwalen im Winter und die herzliche Aloha-Kultur mit Hula und Luau-Festen. Hawaii ist ideal für Strand-, Natur-, Aktiv- und Flitterwochenreisen – die Anreise aus Europa ist allerdings lang.$t$, $t$Hawaii ist ein tropisches Inselparadies im Pazifik und US-Bundesstaat mit Traumstränden, aktiven Vulkanen, üppigem Regenwald, Surfwellen, Walen und der Aloha-Kultur. Die Hauptinseln Oʻahu, Maui, Big Island und Kauaʻi haben je eigenen Charakter. Es eignet sich ideal für Strand-, Natur- und Flitterwochenreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA, die Anreise aus Europa ist lang.$t$, $t$Hawaii ist ganzjährig tropisch warm. Am trockensten ist es von April bis Oktober. Von Dezember bis April kann man Buckelwale beobachten, und im Winter rollen an den Nordküsten die großen Surfwellen.$t$, $t$1 bis 2 Wochen, oft mit zwei Inseln$t$, ARRAY[$t$Strandurlaub$t$,$t$Naturreise$t$,$t$Inselhüpfen$t$,$t$Wandern$t$,$t$Surfen$t$,$t$Flitterwochen$t$,$t$Familien$t$,$t$Abenteuer$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch und Hawaiianisch","flightTime":"Kein Direktflug aus Deutschland; mit Zwischenstopps insgesamt rund 18 bis 22 Stunden, meist über das US-Festland","timezone":"Hawaii-Aleutian Standard Time (UTC−10), ohne Sommerzeit; rund 11 bis 12 Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"April bis Oktober"}$j$::jsonb, $j$["Waikiki Beach und Honolulu auf Oʻahu – Strandleben und Großstadtflair","Pearl Harbor – die historische Gedenkstätte auf Oʻahu","Road to Hana auf Maui – kurvenreiche Panoramastraße durch den Regenwald","Haleakalā – Sonnenaufgang über dem gewaltigen Vulkankrater auf Maui","Volcanoes-Nationalpark auf Big Island – die aktiven Vulkane Kīlauea und Mauna Loa","Nā Pali Coast auf Kauaʻi – dramatische, unzugängliche Steilküste","Waimea Canyon auf Kauaʻi – der „Grand Canyon des Pazifiks“","Walbeobachtung und Aloha-Kultur – Buckelwale im Winter, Hula und Luau"]$j$::jsonb, $j$["Jede Insel hat ihren eigenen Charakter – wer mehrere erleben will, verbindet sie per kurzem Inlandsflug; Oʻahu für Stadt und Strand, Maui und Big Island für Vulkane, Kauaʻi für wilde Natur.","Auf den Inseln ist ein Mietwagen nahezu unverzichtbar, etwa für die Road to Hana oder die Vulkane; der Sonnenaufgang am Haleakalā erfordert eine Reservierung.","Zum Schutz der Korallenriffe ist nur „reef-safe“ Sonnencreme erlaubt – Produkte mit Oxybenzon sind verboten; beim Schnorcheln Korallen niemals berühren.","Die hawaiianische Kultur und Natur verdienen Respekt: heilige Stätten meiden, Wildtiere wie Mönchsrobben und Meeresschildkröten nicht stören und Abstand halten."]$j$::jsonb, $j$[{"question":"Brauche ich für Hawaii ein Visum?","answer":"Hawaii ist ein US-Bundesstaat, daher gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Wie reist man nach Hawaii an?","answer":"Es gibt keine Direktflüge aus Deutschland. Üblich ist die Anreise mit ein bis zwei Zwischenstopps, meist über das US-Festland wie Los Angeles oder San Francisco. Insgesamt sollte man mit rund 18 bis 22 Stunden Reisezeit rechnen."},{"question":"Welche Insel sollte man wählen?","answer":"Das hängt von den Interessen ab: Oʻahu bietet Stadt, Strand und Geschichte, Maui Vulkane und Walbeobachtung, Big Island aktive Vulkane und Vielfalt, Kauaʻi wilde Natur. Wer Zeit hat, kombiniert zwei Inseln per Inlandsflug."},{"question":"Wann ist die beste Reisezeit für Hawaii?","answer":"Hawaii ist ganzjährig warm. Am trockensten ist es von April bis Oktober. Wer Buckelwale sehen möchte, reist zwischen Dezember und April; im Winter sind zudem die großen Surfwellen an den Nordküsten beeindruckend."},{"question":"Welche Währung gilt auf Hawaii?","answer":"Als US-Bundesstaat zahlt man mit dem US-Dollar (USD). Kartenzahlung ist nahezu überall üblich, und wie auf dem Festland kommen Steuern erst an der Kasse hinzu, während Trinkgeld erwartet wird."},{"question":"Braucht man auf Hawaii einen Mietwagen?","answer":"Ja, auf den meisten Inseln ist ein Mietwagen praktisch unverzichtbar, um Strände, Vulkane und Aussichtspunkte zu erreichen. Nur in Waikiki auf Oʻahu kommt man zur Not auch ohne Auto zurecht."},{"question":"Kann man auf Hawaii Wale und Meerestiere sehen?","answer":"Ja, von Dezember bis April ziehen Buckelwale durch die Gewässer, besonders vor Maui. Beim Schnorcheln trifft man oft auf bunte Fische, Meeresschildkröten und mancherorts Delfine. Stets Abstand halten und Tiere nicht berühren."},{"question":"Kann man die Vulkane Hawaiis besuchen?","answer":"Ja, der Hawaii-Volcanoes-Nationalpark auf Big Island ermöglicht eindrucksvolle Einblicke in die aktive Vulkanlandschaft rund um Kīlauea. Die Aktivität schwankt; aktuelle Bedingungen und Sicherheitshinweise sollte man vorab prüfen."},{"question":"Ist Hawaii für Familien und Flitterwochen geeignet?","answer":"Ja, beides. Familien schätzen die Strände, Schnorchelreviere und Naturerlebnisse, während Paare die traumhaften Kulissen, Wasserfälle und Sonnenuntergänge für Flitterwochen lieben. Das Angebot reicht von einfach bis luxuriös."},{"question":"Wie viele Tage sollte man für Hawaii einplanen?","answer":"Wegen der langen Anreise und des Jetlags lohnen sich mindestens 10 Tage. Wer zwei Inseln in Ruhe erleben möchte, plant 2 Wochen ein, um Reisestress zu vermeiden."}]$j$::jsonb, $t$Hawaii Urlaub: Inseln, Vulkane, Strände & beste Reisezeit$t$, $t$Dein Hawaii-Urlaub: Traumstrände, aktive Vulkane, die Road to Hana, Walbeobachtung und die Aloha-Kultur auf Oʻahu, Maui, Big Island und Kauaʻi. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$Hawaii Reise buchen, Flug nach Honolulu, Mietwagen Hawaii, Hotel Waikiki, Inselhüpfen Hawaii, Hawaii Rundreise, Flitterwochen Hawaii$t$, true, $j$["amerika","australien","neuseeland"]$j$::jsonb, ARRAY[$t$Hawaii$t$,$t$Oʻahu$t$,$t$Honolulu$t$,$t$Waikiki Beach$t$,$t$Pearl Harbor$t$,$t$Maui$t$,$t$Road to Hana$t$,$t$Haleakalā$t$,$t$Big Island$t$,$t$Volcanoes-Nationalpark$t$,$t$Kīlauea$t$,$t$Kauaʻi$t$,$t$Nā Pali Coast$t$,$t$Waimea Canyon$t$,$t$Aloha$t$,$t$US-Dollar$t$]::text[], $t$Hawaii ist ein tropisches Inselparadies im Pazifik und der einzige US-Bundesstaat im Ozean, mit Traumstränden, aktiven Vulkanen, üppigem Regenwald, Surfwellen, Walen und der herzlichen Aloha-Kultur. Die Hauptinseln Oʻahu, Maui, Big Island und Kauaʻi haben jeweils ihren eigenen Charakter und lassen sich per Inlandsflug verbinden. Es eignet sich ideal für Strand-, Natur-, Aktiv- und Flitterwochenreisen, am besten von April bis Oktober; für die Einreise gelten die USA-Bestimmungen mit ESTA, und die Anreise aus Europa ist lang.$t$, $t$Hawaii ist ein tropisches Inselparadies im Pazifik mit Traumstränden, aktiven Vulkanen, Surfwellen und der Aloha-Kultur – als US-Bundesstaat mit ESTA-Einreise.$t$, $t$https://www.apearound.de/reiseziele/hawaii$t$, $t$/images/destinations/hawaii.jpg$t$, $t$/images/destinations/hawaii.jpg$t$, $t$Hawaii Urlaub: Inseln, Vulkane, Strände & beste Reisezeit$t$, $t$Dein Hawaii-Urlaub: Traumstrände, aktive Vulkane, die Road to Hana, Walbeobachtung und die Aloha-Kultur auf Oʻahu, Maui, Big Island und Kauaʻi. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$Hawaii Urlaub: Inseln, Vulkane, Strände & beste Reisezeit$t$, $t$Dein Hawaii-Urlaub: Traumstrände, aktive Vulkane, die Road to Hana, Walbeobachtung und die Aloha-Kultur auf Oʻahu, Maui, Big Island und Kauaʻi. Beste Reisezeit, Anreise, Einreise und Tipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Holland
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Holland$t$, $t$holland$t$, $t$Niederlande$t$, $t$Westeuropa$t$, $t$Europa$t$, $t$/images/destinations/holland-hero.jpg$t$, $t$Beliebtes Nachbarland mit Grachten, Tulpenfeldern, Windmühlen, Nordseestränden und fahrradfreundlichen Städten – schnell und unkompliziert erreichbar.$t$, $t$Holland – umgangssprachlich für die Niederlande – zählt zu den beliebtesten Reisezielen der Deutschen, denn es ist nah, vielseitig und unkompliziert. Die Hauptstadt Amsterdam begeistert mit ihren malerischen Grachten, weltbekannten Museen wie dem Rijksmuseum und dem Van-Gogh-Museum sowie dem bewegenden Anne-Frank-Haus. Im Frühling verwandeln die Tulpenfelder rund um den Keukenhof das Land in ein Blütenmeer, während die Windmühlen von Kinderdijk und die Käsemärkte von Alkmaar und Gouda typisch holländisches Flair versprühen. An der Nordsee laden lange Sandstrände in Zeeland, an der Küste von Scheveningen und auf Inseln wie Texel zum Familienurlaub ein. Modern und kreativ zeigt sich Rotterdam mit seiner spektakulären Architektur. Dank des dichten Bahnnetzes und der ausgeprägten Fahrradkultur lässt sich das flache Land besonders entspannt und nachhaltig erkunden.$t$, $t$Holland, umgangssprachlich für die Niederlande, ist ein beliebtes Nachbarland mit Grachtenstädten wie Amsterdam, Tulpenfeldern, Windmühlen, Käsemärkten und Nordseestränden. Es ist schnell erreichbar, sehr fahrradfreundlich und eignet sich ideal für Städtetrips, Familien- und Strandurlaube.$t$, $t$April bis September für mildes Wetter; die Tulpen blühen von Mitte April bis Anfang Mai, die Nordseesaison läuft im Sommer.$t$, $t$Städtereise 2 bis 4 Tage, Strand- oder Rundreise bis zu einer Woche$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Strandurlaub$t$,$t$Radreise$t$,$t$Familien$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Euro (EUR)","language":"Niederländisch","flightTime":"Aus Westdeutschland in 1 bis 2 Stunden per Auto oder Bahn erreichbar; Flüge nach Amsterdam rund 1 Stunde","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis September; Tulpenblüte Mitte April bis Anfang Mai"}$j$::jsonb, $j$["Amsterdam – Grachten, Rijksmuseum, Van-Gogh-Museum und das Anne-Frank-Haus","Keukenhof und die Tulpenfelder – farbenprächtiges Blütenmeer im Frühling","Windmühlen von Kinderdijk – UNESCO-Welterbe und klassisches Holland-Motiv","Nordseeküste – Strände in Zeeland, Scheveningen und auf der Insel Texel","Rotterdam – moderne Architektur, Markthal und lebendige Hafenstadt","Käsemärkte von Alkmaar und Gouda – traditionelles Handwerk zum Anfassen","Giethoorn – idyllisches „Venedig des Nordens“ mit Grachten statt Straßen","Den Haag – Regierungssitz mit dem Mauritshuis und dem Seebad Scheveningen"]$j$::jsonb, $j$["Der Keukenhof hat nur von Ende März bis Mitte Mai geöffnet – wer die Tulpen sehen möchte, sollte den Besuch unbedingt in diesen Zeitraum legen.","Erkunde die Städte wie ein Einheimischer mit dem Fahrrad; in fast allen Orten gibt es günstige Leihräder und ein hervorragendes Radwegenetz.","Für Bus, Bahn und Tram lohnt sich die landesweite OV-Chipkaart oder kontaktloses Bezahlen, um flexibel und ohne Einzeltickets unterwegs zu sein.","Statt des überlaufenen Amsterdam lohnen auch charmante Alternativen wie Haarlem, Utrecht oder Delft mit ähnlichem Grachtenflair, aber weniger Andrang."]$j$::jsonb, $j$[{"question":"Ist Holland dasselbe wie die Niederlande?","answer":"Streng genommen bezeichnet Holland nur zwei Provinzen (Nord- und Südholland), umgangssprachlich wird der Begriff aber häufig für das ganze Land verwendet. Der offizielle Staatsname lautet Niederlande."},{"question":"Wann ist die beste Reisezeit für Holland?","answer":"Am angenehmsten ist es von April bis September. Wer die berühmten Tulpenfelder erleben möchte, reist zwischen Mitte April und Anfang Mai; die Nordseesaison läuft im Sommer."},{"question":"Brauche ich in Holland ein Auto?","answer":"Für Städtereisen ist ein Auto nicht nötig, da Bahn, Tram und vor allem das Fahrrad hervorragend funktionieren. Für einen Strandurlaub an der Nordsee oder in Zeeland reisen viele jedoch bequem mit dem eigenen Auto an."},{"question":"Welche Währung gilt in Holland?","answer":"In den Niederlanden zahlt man mit dem Euro (EUR). Kartenzahlung ist sehr verbreitet, vielerorts wird sogar bevorzugt mit Karte oder kontaktlos bezahlt."},{"question":"Wann blühen die Tulpen in Holland?","answer":"Die Tulpen blühen je nach Wetter von Mitte April bis Anfang Mai. Der bekannteste Ort ist der Keukenhof bei Lisse, der nur in diesem Zeitraum geöffnet ist; auch die umliegenden Felder bieten sich für Radtouren an."},{"question":"Welche Sehenswürdigkeiten sollte man in Amsterdam nicht verpassen?","answer":"Zu den Höhepunkten zählen eine Grachtenfahrt, das Rijksmuseum, das Van-Gogh-Museum, das Anne-Frank-Haus sowie ein Bummel durch den Jordaan und über die Blumenmärkte. Tickets für beliebte Museen sollte man vorab buchen."},{"question":"Ist Holland für einen Familienurlaub geeignet?","answer":"Ja, Holland ist sehr familienfreundlich. Flache Nordseestrände, der Freizeitpark Efteling, kindgerechte Städte und sichere Radwege machen das Land zu einem idealen Ziel für Familien."},{"question":"Wie sind die Coffeeshops in Holland geregelt?","answer":"In den Niederlanden wird der Verkauf kleiner Mengen Cannabis in lizenzierten Coffeeshops geduldet. Die Regeln und Altersgrenzen werden kontrolliert, und manche Städte schränken den Zugang für Touristen ein. Beim Mitführen über die Grenze droht in Deutschland Strafbarkeit."},{"question":"Spricht man in Holland Deutsch oder Englisch?","answer":"Viele Niederländer sprechen sehr gut Englisch, und in grenznahen sowie touristischen Gebieten oft auch Deutsch. Die Verständigung ist für deutsche Reisende daher unkompliziert."},{"question":"Lohnt sich Holland auch außerhalb von Amsterdam?","answer":"Auf jeden Fall. Städte wie Rotterdam, Utrecht, Delft, Haarlem und Den Haag, die Windmühlen von Kinderdijk, das Wasserdorf Giethoorn und die Nordseeküste bieten viel Abwechslung und sind oft weniger überlaufen."},{"question":"Wie viele Tage sollte man für Holland einplanen?","answer":"Für einen Städtetrip nach Amsterdam reichen 2 bis 4 Tage. Wer mehrere Städte, die Küste und Sehenswürdigkeiten wie Kinderdijk verbinden möchte, plant am besten bis zu einer Woche ein."}]$j$::jsonb, $t$Holland Urlaub: Amsterdam, Tulpen, Strände & beste Reisezeit$t$, $t$Dein Holland-Urlaub: Amsterdam mit Grachten, Tulpenfelder, Windmühlen von Kinderdijk und Nordseestrände. Beste Reisezeit, Sehenswürdigkeiten und praktische Reisetipps im Überblick.$t$, $t$Holland Urlaub buchen, Hotel Amsterdam, Ferienhaus Nordsee Holland, Städtereise Amsterdam, Ferienpark Niederlande, Strandurlaub Zeeland$t$, false, $j$["belgien","daenemark","frankreich"]$j$::jsonb, ARRAY[$t$Holland$t$,$t$Niederlande$t$,$t$Amsterdam$t$,$t$Grachten$t$,$t$Keukenhof$t$,$t$Tulpenfelder$t$,$t$Kinderdijk$t$,$t$Windmühlen$t$,$t$Rotterdam$t$,$t$Den Haag$t$,$t$Scheveningen$t$,$t$Texel$t$,$t$Zeeland$t$,$t$Giethoorn$t$,$t$Gouda$t$,$t$Rijksmuseum$t$]::text[], $t$Holland ist die umgangssprachliche Bezeichnung für die Niederlande und ein bei Deutschen sehr beliebtes Nachbarland mit Grachtenstädten wie Amsterdam, Tulpenfeldern, Windmühlen, Käsemärkten und Nordseestränden. Das flache Land ist schnell erreichbar, äußerst fahrradfreundlich und eignet sich ideal für Städtetrips, Familien- und Strandurlaube. Die beste Reisezeit liegt zwischen April und September, die Tulpen blühen von Mitte April bis Anfang Mai.$t$, $t$Holland (Niederlande) ist ein beliebtes Nachbarland mit Amsterdam, Grachten, Tulpenfeldern, Windmühlen und Nordseestränden, ideal für Städte- und Familienurlaube.$t$, $t$https://www.apearound.de/reiseziele/holland$t$, $t$/images/destinations/holland.jpg$t$, $t$/images/destinations/holland.jpg$t$, $t$Holland Urlaub: Amsterdam, Tulpen, Strände & beste Reisezeit$t$, $t$Dein Holland-Urlaub: Amsterdam mit Grachten, Tulpenfelder, Windmühlen von Kinderdijk und Nordseestrände. Beste Reisezeit, Sehenswürdigkeiten und praktische Reisetipps im Überblick.$t$, $t$Holland Urlaub: Amsterdam, Tulpen, Strände & beste Reisezeit$t$, $t$Dein Holland-Urlaub: Amsterdam mit Grachten, Tulpenfelder, Windmühlen von Kinderdijk und Nordseestrände. Beste Reisezeit, Sehenswürdigkeiten und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Indonesien
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Indonesien$t$, $t$indonesien$t$, $t$Indonesien$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/indonesien-hero.jpg$t$, $t$Gewaltiger Inselstaat mit Bali, Traumstränden, rauchenden Vulkanen, uralten Tempeln, Komodowaranen und einigen der besten Tauchgründe der Welt.$t$, $t$Indonesien ist mit über 17.000 Inseln der größte Inselstaat der Erde und ein Reiseziel von überwältigender Vielfalt. Im Mittelpunkt steht die „Insel der Götter“ Bali mit ihren Reisterrassen, Tempeln, dem kreativen Zentrum Ubud und Stränden für Surfer und Sonnenanbeter. Doch das Land bietet weit mehr: Auf Java thronen die monumentalen Tempelanlagen Borobudur und Prambanan, der Vulkan Bromo und der Ijen mit seinen blauen Schwefelflammen bieten unvergessliche Naturschauspiele. Der Komodo-Nationalpark beherbergt die urzeitlichen Komodowarane und spektakuläre Tauchgründe, während Raja Ampat in Papua als eines der artenreichsten Tauchparadiese der Welt gilt. Auf Sumatra und Borneo lassen sich frei lebende Orang-Utans erleben, und die Gili-Inseln vor Lombok laden zum Entspannen ein. Mit warmem Klima, herzlichen Menschen, reicher Kultur und fairen Preisen ist Indonesien ideal für Strand-, Natur-, Tauch- und Rundreisen.$t$, $t$Indonesien ist der größte Inselstaat der Erde mit Bali, Traumstränden, Vulkanen wie Bromo und Ijen, den Tempeln Borobudur und Prambanan, den Komodowaranen und erstklassigen Tauchgründen wie Raja Ampat. Das Land bietet enorme Vielfalt zu fairen Preisen und eignet sich ideal für Strand-, Natur-, Tauch- und Rundreisen.$t$, $t$Die beste Reisezeit ist die Trockenzeit von April bis Oktober, besonders für Bali, Java und Komodo; von November bis März herrscht Regenzeit.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Rundreise$t$,$t$Tauchen$t$,$t$Surfen$t$,$t$Naturreise$t$,$t$Backpacking$t$,$t$Kulturreise$t$]::text[], $j${"currency":"Indonesische Rupiah (IDR)","language":"Indonesisch (Bahasa Indonesia)","flightTime":"ca. 14 bis 16 Stunden mit Zwischenstopp (Jakarta, Denpasar auf Bali)","timezone":"Drei Zeitzonen (UTC+7 bis UTC+9); Bali liegt bei UTC+8, sieben Stunden vor MEZ","visa":"Visum erforderlich; als Visa on Arrival oder E-Visa on Arrival (in der Regel 30 Tage, verlängerbar) erhältlich","bestMonths":"April bis Oktober"}$j$::jsonb, $j$["Bali – Reisterrassen, Tempel, Ubud und Strände für Surfer und Erholungssuchende","Borobudur und Prambanan – monumentale Tempelanlagen auf Java, UNESCO-Welterbe","Vulkane Bromo und Ijen – Sonnenaufgänge und die berühmten blauen Schwefelflammen","Komodo-Nationalpark – urzeitliche Komodowarane und spektakuläre Tauchgründe","Gili-Inseln und Lombok – türkises Wasser, Schnorcheln und entspanntes Inselleben","Raja Ampat – eines der artenreichsten Tauchparadiese der Welt in Papua","Orang-Utans auf Sumatra und Borneo – etwa rund um Bukit Lawang","Nusa Penida – dramatische Klippen und Traumstrände nahe Bali"]$j$::jsonb, $j$["Bali ist im Süden oft überlaufen – ruhiger und ursprünglicher wird es im kreativen Ubud sowie im Norden und Osten der Insel.","Den Komodo-Nationalpark erreicht man über Labuan Bajo auf Flores; eine mehrtägige Bootstour verbindet Warane, Pink Beach und erstklassiges Tauchen.","Die Wanderung zum Ijen startet nachts, um die surrealen blauen Flammen zu sehen, während der Sonnenaufgang am Bromo zu den schönsten Indonesiens zählt.","Fällt die Reise auf Bali mit dem Neujahrsfest Nyepi zusammen, steht die ganze Insel einen Tag lang still – ein besonderes, aber einschränkendes Erlebnis."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Indonesien?","answer":"Ja, deutsche Staatsbürger benötigen ein Visum. Es ist als Visa on Arrival bei der Einreise oder bequem als E-Visa on Arrival vorab online erhältlich, gilt in der Regel für 30 Tage und ist einmalig verlängerbar. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Indonesien?","answer":"Ideal ist die Trockenzeit von April bis Oktober, besonders für Bali, Java und Komodo. Von November bis März herrscht Regenzeit mit höherer Luftfeuchtigkeit und häufigeren Schauern."},{"question":"Welche Währung gilt in Indonesien?","answer":"Gezahlt wird mit der Indonesischen Rupiah (IDR). In touristischen Gebieten ist Kartenzahlung möglich, an Märkten und in kleinen Orten ist jedoch Bargeld wichtig. Die hohen Beträge mit vielen Nullen sorgen anfangs oft für Verwirrung."},{"question":"Gibt es auf Bali eine Touristenabgabe?","answer":"Ja, Bali erhebt eine Touristenabgabe (Tourist Levy), die pro Person zu entrichten ist. Sie kann bequem vorab online oder bei der Ankunft bezahlt werden und kommt dem Erhalt von Kultur und Umwelt zugute."},{"question":"Wie reist man innerhalb Indonesiens?","answer":"Wegen der riesigen Distanzen sind Inlandsflüge das wichtigste Verkehrsmittel, dazu kommen Fähren zwischen den Inseln. Auf Bali sind Roller verbreitet, ein privater Fahrer für den Tag ist jedoch günstig, bequem und sicherer. Ein eigener Mietwagen ist unüblich."},{"question":"Ist Indonesien für Taucher geeignet?","answer":"Ja, Indonesien zählt zu den besten Tauchdestinationen der Welt. Top-Reviere sind Raja Ampat, Komodo, die Gewässer um die Gili-Inseln und Nusa Penida mit Mantarochen. Es gibt Spots für alle Erfahrungsstufen."},{"question":"Kann man in Indonesien das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln sowie rohen Speisen vorsichtig sein."},{"question":"Welche Impfungen werden für Indonesien empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Ist Indonesien für einen Familienurlaub geeignet?","answer":"Ja, besonders Bali ist familienfreundlich mit ruhigen Stränden, Wasserparks, Reisfeldern und Tiererlebnissen. Für weite Strecken und mehrere Inseln sollte man wegen der Reisezeiten etwas großzügiger planen."},{"question":"Ist Indonesien sicher für Reisende?","answer":"Ja, Indonesien gilt überwiegend als sicheres Reiseland mit gastfreundlichen Menschen. Vorsicht ist im Straßenverkehr und beim Rollerfahren geboten. Da das Land in einer aktiven Vulkanregion liegt, sollte man aktuelle Hinweise beachten."},{"question":"Welche Gerichte sollte man in Indonesien probieren?","answer":"Typisch sind Nasi Goreng (gebratener Reis), Mie Goreng (gebratene Nudeln), Satay-Spieße, Gado-Gado und Babi Guling auf Bali. Tropische Früchte und der indonesische Kaffee runden das kulinarische Erlebnis ab."},{"question":"Wie viele Tage sollte man für Indonesien einplanen?","answer":"Für Bali allein reicht etwa eine Woche. Wer Bali mit Java, Komodo oder weiteren Inseln verbinden möchte, sollte wegen der Distanzen 2 bis 3 Wochen einplanen."}]$j$::jsonb, $t$Indonesien Urlaub: Bali, Vulkane, Reisetipps & beste Reisezeit$t$, $t$Dein Indonesien-Urlaub: Bali, die Tempel Borobudur und Prambanan, Vulkane wie Bromo und Ijen, Komodowarane und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Indonesien Reise buchen, Flug nach Bali oder Jakarta, Hotel Bali, Rundreise Indonesien, Tauchreise Komodo oder Raja Ampat, Backpacking Südostasien$t$, false, $j$["thailand","malaysia","philippinen"]$j$::jsonb, ARRAY[$t$Indonesien$t$,$t$Bali$t$,$t$Ubud$t$,$t$Borobudur$t$,$t$Prambanan$t$,$t$Java$t$,$t$Bromo$t$,$t$Ijen$t$,$t$Komodo-Nationalpark$t$,$t$Komodowarane$t$,$t$Gili-Inseln$t$,$t$Lombok$t$,$t$Raja Ampat$t$,$t$Nusa Penida$t$,$t$Indonesische Rupiah$t$,$t$Nasi Goreng$t$]::text[], $t$Indonesien ist mit über 17.000 Inseln der größte Inselstaat der Erde, bekannt für Bali, Traumstrände, Vulkane wie Bromo und Ijen, die Tempel Borobudur und Prambanan, die Komodowarane und erstklassige Tauchgründe wie Raja Ampat. Das Land bietet enorme landschaftliche und kulturelle Vielfalt zu fairen Preisen und eignet sich ideal für Strand-, Natur-, Tauch- und Rundreisen. Die beste Reisezeit ist die Trockenzeit von April bis Oktober.$t$, $t$Indonesien ist der größte Inselstaat der Erde mit Bali, Vulkanen, den Tempeln Borobudur und Prambanan, Komodowaranen und Top-Tauchgründen, am besten von April bis Oktober.$t$, $t$https://www.apearound.de/reiseziele/indonesien$t$, $t$/images/destinations/indonesien.jpg$t$, $t$/images/destinations/indonesien.jpg$t$, $t$Indonesien Urlaub: Bali, Vulkane, Reisetipps & beste Reisezeit$t$, $t$Dein Indonesien-Urlaub: Bali, die Tempel Borobudur und Prambanan, Vulkane wie Bromo und Ijen, Komodowarane und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Indonesien Urlaub: Bali, Vulkane, Reisetipps & beste Reisezeit$t$, $t$Dein Indonesien-Urlaub: Bali, die Tempel Borobudur und Prambanan, Vulkane wie Bromo und Ijen, Komodowarane und Top-Tauchgründe. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Irland
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Irland$t$, $t$irland$t$, $t$Irland$t$, $t$Westeuropa$t$, $t$Europa$t$, $t$/images/destinations/irland-hero.jpg$t$, $t$Die grüne Insel mit dramatischen Steilküsten, sanften Hügeln, mittelalterlichen Burgen, lebendigem Dublin, Guinness und herzlicher Pub-Kultur.$t$, $t$Irland, die „grüne Insel“, begeistert mit sattgrünen Landschaften, einer dramatischen Atlantikküste und einer einzigartig herzlichen, geselligen Kultur. Die Hauptstadt Dublin verbindet Geschichte und Lebensfreude: vom Book of Kells im Trinity College über das Guinness Storehouse bis zum lebhaften Ausgehviertel Temple Bar mit seiner traditionellen Live-Musik. Das Herz Irlands sind jedoch seine Naturschönheiten – allen voran die gewaltigen Cliffs of Moher, die über 200 Meter steil ins Meer abfallen. Panoramarouten wie der Ring of Kerry und der Wild Atlantic Way entlang der Westküste zählen zu den schönsten Roadtrips Europas und führen durch wilde Regionen wie Connemara und die Dingle-Halbinsel. Mittelalterliche Stätten wie der Rock of Cashel und das prähistorische Newgrange, das älter ist als die ägyptischen Pyramiden, erzählen von einer reichen Vergangenheit. Mit seiner Mischung aus Natur, Geschichte und Geselligkeit ist Irland ideal für Roadtrips, Wander- und Kulturreisen und von Deutschland aus schnell erreichbar.$t$, $t$Irland ist die „grüne Insel“ mit dramatischen Steilküsten wie den Cliffs of Moher, Panoramarouten wie dem Wild Atlantic Way und dem Ring of Kerry, dem lebendigen Dublin und herzlicher Pub-Kultur. Es eignet sich ideal für Roadtrips, Natur- und Kulturreisen und ist von Deutschland aus schnell erreichbar.$t$, $t$Mai bis September für möglichst mildes Wetter und lange Tage; das Wetter bleibt jedoch ganzjährig wechselhaft, weshalb der April und Frühherbst ebenfalls reizvoll sind.$t$, $t$rund eine Woche$t$, ARRAY[$t$Roadtrip$t$,$t$Naturreise$t$,$t$Kulturreise$t$,$t$Wandern$t$,$t$Geschichtsreise$t$,$t$Familien$t$]::text[], $j${"currency":"Euro (EUR)","language":"Englisch und Irisch (Gälisch)","flightTime":"ca. 2 bis 2,5 Stunden ab Deutschland (Dublin)","timezone":"GMT (UTC+0), eine Stunde hinter MEZ","visa":"Nicht erforderlich für EU-Bürger; Irland gehört zur EU, jedoch nicht zum Schengen-Raum (keine ETA nötig)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Dublin – Trinity College mit dem Book of Kells, Temple Bar und Guinness Storehouse","Cliffs of Moher – über 200 Meter hohe Steilklippen am Atlantik","Ring of Kerry – eine der schönsten Panoramastraßen Europas","Wild Atlantic Way – spektakuläre Küstenroute entlang der Westküste","Connemara und die Dingle-Halbinsel – wilde, ursprüngliche Landschaften","Rock of Cashel – beeindruckende mittelalterliche Burg- und Kirchenanlage","Killarney-Nationalpark – Seen, Wälder und Berge im Südwesten","Newgrange – prähistorisches Ganggrab, älter als die ägyptischen Pyramiden"]$j$::jsonb, $j$["Der Wild Atlantic Way entlang der Westküste ist einer der schönsten Roadtrips Europas und lässt sich gut in Etappen erkunden.","Echte irische Lebensfreude erlebt man bei einer traditionellen Live-Musik-Session (Trad Session) in einem urigen Pub.","Die Cliffs of Moher sind am frühen Morgen oder am späten Nachmittag am stimmungsvollsten und am wenigsten überlaufen.","Das Wetter ist wechselhaft – wer in mehreren Schichten und mit wetterfester Jacke unterwegs ist, bleibt für jede Lage gewappnet."]$j$::jsonb, $j$[{"question":"Brauche ich für Irland ein Visum oder eine ETA?","answer":"Nein. Irland ist EU-Mitglied, daher benötigen EU-Bürger kein Visum. Anders als für das Vereinigte Königreich ist auch keine ETA nötig, da Irland nicht zum Schengen-Raum, aber zur EU gehört. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Welche Währung gilt in Irland?","answer":"In der Republik Irland zahlt man mit dem Euro (EUR). Im britischen Nordirland gilt dagegen das Britische Pfund. Kartenzahlung ist nahezu überall möglich."},{"question":"Wann ist die beste Reisezeit für Irland?","answer":"Am angenehmsten ist es von Mai bis September mit milderem Wetter und langen Tagen. Das berühmt wechselhafte Wetter mit Regen kann jedoch zu jeder Jahreszeit auftreten, weshalb wetterfeste Kleidung wichtig ist."},{"question":"Fährt man in Irland links?","answer":"Ja, in Irland herrscht Linksverkehr. Auf den oft schmalen Landstraßen ist eine vorsichtige Fahrweise ratsam. In Dublin ist ein Auto wegen des guten Nahverkehrs nicht nötig."},{"question":"Lohnt sich ein Mietwagen in Irland?","answer":"Ja, für Roadtrips wie den Ring of Kerry oder den Wild Atlantic Way und zur Erkundung der ländlichen Regionen ist ein Mietwagen ideal. Dublin selbst lässt sich gut zu Fuß und mit öffentlichen Verkehrsmitteln erkunden."},{"question":"Was ist der Unterschied zwischen Irland und Nordirland?","answer":"Die Republik Irland ist ein eigenständiger EU-Staat mit dem Euro, während Nordirland zum Vereinigten Königreich gehört, das Britische Pfund nutzt und für das eine ETA nötig ist. Beide teilen sich die Insel."},{"question":"Sind die Cliffs of Moher einen Besuch wert?","answer":"Ja, die Cliffs of Moher zählen zu den eindrucksvollsten Steilküsten Europas. Bei klarem Wetter reicht der Blick weit über den Atlantik; am schönsten ist es früh am Morgen oder zum Sonnenuntergang."},{"question":"Ist Irland für einen Familienurlaub geeignet?","answer":"Ja, Irland ist familienfreundlich und sicher. Burgen, Tierbeobachtungen, Strände, einfache Wanderungen und die herzliche Gastfreundschaft sorgen für ein entspanntes Reiseerlebnis mit Kindern."},{"question":"Spricht man in Irland Englisch?","answer":"Ja, Englisch ist die Hauptsprache und überall verständlich. Irisch (Gälisch) ist zweite Amtssprache und vor allem im Westen sowie auf Ortsschildern präsent. Die Verständigung ist für deutsche Reisende unkompliziert."},{"question":"Wie viele Tage sollte man für Irland einplanen?","answer":"Für Dublin und einen ersten Eindruck reichen einige Tage. Für eine Rundreise mit Westküste, Cliffs of Moher und Ring of Kerry sollte man rund eine Woche oder mehr einplanen."}]$j$::jsonb, $t$Irland Urlaub: Cliffs of Moher, Roadtrip, Tipps & beste Reisezeit$t$, $t$Dein Irland-Urlaub: die grüne Insel mit den Cliffs of Moher, dem Wild Atlantic Way, dem Ring of Kerry, Dublin und herzlicher Pub-Kultur. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Irland Reise buchen, Flug nach Dublin, Hotel Dublin, Mietwagen Irland vergleichen, Roadtrip Wild Atlantic Way, Rundreise Irland$t$, true, $j$["schottland","england","island"]$j$::jsonb, ARRAY[$t$Irland$t$,$t$Dublin$t$,$t$Trinity College$t$,$t$Book of Kells$t$,$t$Temple Bar$t$,$t$Guinness$t$,$t$Cliffs of Moher$t$,$t$Ring of Kerry$t$,$t$Wild Atlantic Way$t$,$t$Connemara$t$,$t$Dingle-Halbinsel$t$,$t$Rock of Cashel$t$,$t$Killarney-Nationalpark$t$,$t$Newgrange$t$,$t$Galway$t$]::text[], $t$Irland, die „grüne Insel“, begeistert mit dramatischen Steilküsten wie den Cliffs of Moher, Panoramarouten wie dem Wild Atlantic Way und dem Ring of Kerry, dem lebendigen Dublin mit Guinness Storehouse und Temple Bar sowie herzlicher Pub-Kultur. Das Land eignet sich ideal für Roadtrips, Natur- und Kulturreisen und ist von Deutschland aus schnell erreichbar. Als EU-Land mit Euro ist für Irland – anders als für das britische Nordirland – keine ETA nötig.$t$, $t$Irland ist die grüne Insel mit den Cliffs of Moher, dem Wild Atlantic Way, dem Ring of Kerry, Dublin und herzlicher Pub-Kultur – als EU-Land ohne ETA bereisbar.$t$, $t$https://www.apearound.de/reiseziele/irland$t$, $t$/images/destinations/irland.jpg$t$, $t$/images/destinations/irland.jpg$t$, $t$Irland Urlaub: Cliffs of Moher, Roadtrip, Tipps & beste Reisezeit$t$, $t$Dein Irland-Urlaub: die grüne Insel mit den Cliffs of Moher, dem Wild Atlantic Way, dem Ring of Kerry, Dublin und herzlicher Pub-Kultur. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Irland Urlaub: Cliffs of Moher, Roadtrip, Tipps & beste Reisezeit$t$, $t$Dein Irland-Urlaub: die grüne Insel mit den Cliffs of Moher, dem Wild Atlantic Way, dem Ring of Kerry, Dublin und herzlicher Pub-Kultur. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Island
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Island$t$, $t$island$t$, $t$Island$t$, $t$Nordeuropa$t$, $t$Europa$t$, $t$/images/destinations/island-hero.jpg$t$, $t$Insel aus Feuer und Eis mit Vulkanen, Gletschern, tosenden Wasserfällen, Geysiren, heißen Quellen, Nordlichtern und der spektakulären Ringstraße.$t$, $t$Island ist ein faszinierendes Land der Extreme, in dem Feuer und Eis aufeinandertreffen. Auf vergleichsweise kleinem Raum reihen sich aktive Vulkane, mächtige Gletscher, tosende Wasserfälle, brodelnde Geysire und dampfende heiße Quellen aneinander. Der berühmte Golden Circle verbindet den Nationalpark Þingvellir, den Geysir Strokkur und den gewaltigen Wasserfall Gullfoss. Entlang der Südküste beeindrucken Wasserfälle wie Seljalandsfoss und Skógafoss, der schwarze Strand Reynisfjara sowie die magische Gletscherlagune Jökulsárlón mit dem Diamond Beach. Die Hauptstadt Reykjavík überrascht mit ihrer markanten Kirche Hallgrímskirkja und lebendiger Kultur. Im Winter tanzen die Nordlichter über den Himmel, im Sommer sorgt die Mitternachtssonne für taghelle Nächte und macht das Hochland zugänglich. Ein Bad in einer geothermalen Lagune wie der Blauen Lagune gehört ebenso dazu wie ein Roadtrip auf der Ringstraße rund um die Insel. Island ist ideal für Natur-, Roadtrip- und Abenteuerreisen.$t$, $t$Island ist eine Insel aus Feuer und Eis mit Vulkanen, Gletschern, Wasserfällen, Geysiren, heißen Quellen und Nordlichtern. Höhepunkte sind der Golden Circle, die Gletscherlagune Jökulsárlón, die Blaue Lagune und die Ringstraße. Das Land eignet sich ideal für Natur-, Roadtrip- und Abenteuerreisen und ist von Deutschland aus in rund 3,5 Stunden erreichbar.$t$, $t$Juni bis August für Mitternachtssonne, mildes Wetter und zugängliches Hochland; September bis März für die Nordlichter. Jede Jahreszeit hat ihren eigenen Reiz.$t$, $t$rund eine Woche$t$, ARRAY[$t$Naturreise$t$,$t$Roadtrip$t$,$t$Abenteuer$t$,$t$Wandern$t$,$t$Nordlichter$t$,$t$Fotoreise$t$]::text[], $j${"currency":"Isländische Krone (ISK); Island ist nahezu bargeldlos, Kartenzahlung ist überall üblich","language":"Isländisch; Englisch ist weit verbreitet","flightTime":"ca. 3,5 Stunden ab Deutschland (Keflavík bei Reykjavík)","timezone":"GMT (UTC+0), eine Stunde hinter MEZ; keine Zeitumstellung","visa":"Nicht erforderlich; Island gehört zum Schengen-Raum (jedoch nicht zur EU)","bestMonths":"Juni bis August sowie September bis März für Nordlichter"}$j$::jsonb, $j$["Golden Circle – Þingvellir-Nationalpark, der Geysir Strokkur und der Wasserfall Gullfoss","Blaue Lagune – berühmtes geothermales Thermalbad nahe Reykjavík","Jökulsárlón – Gletscherlagune mit treibenden Eisbergen und dem Diamond Beach","Südküste – Wasserfälle Seljalandsfoss und Skógafoss sowie der schwarze Strand Reynisfjara","Reykjavík – nördlichste Hauptstadt der Welt mit der Hallgrímskirkja","Nordlichter – Polarlichter über dem Winterhimmel","Vatnajökull – größter Gletscher Europas mit Eishöhlen","Ringstraße (Route 1) – Roadtrip rund um die ganze Insel"]$j$::jsonb, $j$["Wer Zeit hat, sollte die Ringstraße (Route 1) fahren, um die ganze Insel mit ihren unterschiedlichen Landschaften zu erleben.","Statt der teuren Blauen Lagune lohnen sich auch günstigere geothermale Bäder wie die örtlichen Schwimmbäder, die Sky Lagoon oder die Secret Lagoon.","Da Island sehr teuer ist, sparen Selbstversorger mit Einkäufen in günstigen Supermärkten wie Bónus oder Krónan.","Das Wetter und die Straßenverhältnisse ändern sich schnell – vor Touren unbedingt die offiziellen Seiten road.is und safetravel.is prüfen."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Island?","answer":"Der Sommer (Juni bis August) bietet mildes Wetter, die Mitternachtssonne und zugängliches Hochland. Für die Nordlichter reist man zwischen September und März in den dunklen Monaten. Jede Jahreszeit hat ihren eigenen Reiz."},{"question":"Welche Währung gilt in Island?","answer":"In Island zahlt man mit der Isländischen Krone (ISK). Das Land ist nahezu bargeldlos, sodass Kartenzahlung und kontaktloses Bezahlen praktisch überall möglich und üblich sind – Bargeld braucht man kaum."},{"question":"Brauche ich ein Visum für Island?","answer":"Nein. Island gehört zwar nicht zur EU, ist aber Teil des Schengen-Raums. EU-Bürger benötigen kein Visum; ein gültiger Personalausweis oder Reisepass genügt."},{"question":"Lohnt sich ein Mietwagen in Island?","answer":"Ja, ein Mietwagen ist fast unverzichtbar, da der öffentliche Nahverkehr außerhalb von Reykjavík sehr begrenzt ist. Für das Hochland und die F-Straßen, die nur im Sommer befahrbar sind, ist ein Allradfahrzeug nötig."},{"question":"Ist Island ein teures Reiseland?","answer":"Ja, Island zählt zu den teuersten Reiseländern der Welt, besonders bei Unterkünften, Restaurants und Alkohol. Mit Selbstverpflegung, günstigen Supermärkten und früher Buchung lässt sich jedoch sparen."},{"question":"Wann und wo sieht man die Nordlichter?","answer":"Die besten Chancen auf Polarlichter hat man von September bis März in dunklen, klaren Nächten abseits der Stadtlichter. Mehrere Übernachtungen und etwas Geduld erhöhen die Wahrscheinlichkeit deutlich."},{"question":"Lohnt sich die Blaue Lagune?","answer":"Die Blaue Lagune ist ein beliebtes Erlebnis mit milchig-blauem, geothermalem Wasser. Sie ist allerdings teuer und sollte vorab gebucht werden. Günstigere Alternativen sind die örtlichen Thermalbäder oder die Sky Lagoon."},{"question":"Beeinflussen Vulkanausbrüche Reisen nach Island?","answer":"Auf der Reykjanes-Halbinsel kommt es periodisch zu Vulkanausbrüchen, die zeitweise das Gebiet um Grindavík und die Blaue Lagune betreffen können. Das übrige Land ist davon meist nicht betroffen; aktuelle Informationen findet man auf safetravel.is."},{"question":"Ist Island für einen Familienurlaub geeignet?","answer":"Ja, Island ist sehr sicher und familienfreundlich. Wasserfälle, Geothermalbäder, Wal- und Papageitaucher-Beobachtungen sowie die spektakuläre Natur begeistern auch Kinder. Für Roadtrips sollte man die Etappen kindgerecht planen."},{"question":"Was ist die Mitternachtssonne?","answer":"Im Hochsommer geht die Sonne in Island kaum unter, sodass es nachts taghell bleibt. Diese Mitternachtssonne ermöglicht lange Ausflüge und ein besonderes Lichterlebnis in der Natur."},{"question":"Wie viele Tage sollte man für Island einplanen?","answer":"Für Reykjavík, den Golden Circle und die Südküste reichen einige Tage. Für eine komplette Umrundung auf der Ringstraße sollte man mindestens eine Woche, besser 8 bis 10 Tage einplanen."}]$j$::jsonb, $t$Island Urlaub: Vulkane, Nordlichter, Ringstraße & beste Reisezeit$t$, $t$Dein Island-Urlaub: Vulkane und Gletscher, der Golden Circle, die Blaue Lagune, Wasserfälle, Nordlichter und die Ringstraße. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Island Reise buchen, Flug nach Reykjavík, Hotel Island, Mietwagen Island vergleichen, Roadtrip Ringstraße, Nordlichter-Reise Island, Mietwohnmobil Island$t$, true, $j$["norwegen","schottland","irland"]$j$::jsonb, ARRAY[$t$Island$t$,$t$Reykjavík$t$,$t$Golden Circle$t$,$t$Þingvellir$t$,$t$Geysir Strokkur$t$,$t$Gullfoss$t$,$t$Blaue Lagune$t$,$t$Jökulsárlón$t$,$t$Diamond Beach$t$,$t$Seljalandsfoss$t$,$t$Skógafoss$t$,$t$Reynisfjara$t$,$t$Vatnajökull$t$,$t$Nordlichter$t$,$t$Ringstraße$t$,$t$Isländische Krone$t$]::text[], $t$Island ist eine Insel aus Feuer und Eis mit Vulkanen, Gletschern, tosenden Wasserfällen, Geysiren, heißen Quellen und Nordlichtern. Höhepunkte sind der Golden Circle, die Gletscherlagune Jökulsárlón, die Blaue Lagune und ein Roadtrip auf der Ringstraße. Das Land eignet sich ideal für Natur-, Roadtrip- und Abenteuerreisen; im Sommer locken Mitternachtssonne und Hochland, im Winter die Polarlichter.$t$, $t$Island ist eine Insel aus Feuer und Eis mit Vulkanen, Gletschern, Wasserfällen, Geysiren, Nordlichtern und der spektakulären Ringstraße.$t$, $t$https://www.apearound.de/reiseziele/island$t$, $t$/images/destinations/island.jpg$t$, $t$/images/destinations/island.jpg$t$, $t$Island Urlaub: Vulkane, Nordlichter, Ringstraße & beste Reisezeit$t$, $t$Dein Island-Urlaub: Vulkane und Gletscher, der Golden Circle, die Blaue Lagune, Wasserfälle, Nordlichter und die Ringstraße. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Island Urlaub: Vulkane, Nordlichter, Ringstraße & beste Reisezeit$t$, $t$Dein Island-Urlaub: Vulkane und Gletscher, der Golden Circle, die Blaue Lagune, Wasserfälle, Nordlichter und die Ringstraße. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Italien
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Italien$t$, $t$italien$t$, $t$Italien$t$, $t$Südeuropa$t$, $t$Europa$t$, $t$/images/destinations/italien-hero.jpg$t$, $t$Sehnsuchtsland am Mittelmeer mit Rom, Venedig, der Toskana, der Amalfiküste, Bergseen, weltbester Küche und unzähligen Kunstschätzen.$t$, $t$Italien ist eines der beliebtesten Reiseländer der Welt und vereint Geschichte, Kunst, Küste und Kulinarik wie kaum ein anderes Land. Die Ewige Stadt Rom beeindruckt mit Kolosseum, Forum Romanum und dem Vatikan, das einzigartige Venedig mit seinen Kanälen und dem Markusplatz. Florenz und die sanften Hügel der Toskana stehen für Renaissancekunst, Chianti-Weine und Zypressenalleen. Im Süden lockt die spektakuläre Amalfiküste mit der Insel Capri, während Sizilien mit dem Ätna, antiken Tempeln und Taormina fasziniert. Wer es alpiner mag, findet am Gardasee, Comer See und in den Dolomiten Südtirols traumhafte Natur. Mailand ist das Zentrum für Mode und Design. Dazu kommt die weltberühmte italienische Küche mit Pizza, Pasta, Espresso und Gelato sowie die entspannte Aperitivo- und Piazza-Kultur. Ob Städtetrip, Strandurlaub, Roadtrip oder Genussreise – Italien ist von Deutschland aus bequem erreichbar und immer eine Reise wert.$t$, $t$Italien ist ein vielseitiges Reiseland am Mittelmeer mit Städten wie Rom, Venedig, Florenz und Mailand, der Toskana, der Amalfiküste, Sizilien sowie den Bergseen und Dolomiten im Norden. Berühmt für Kunst, Geschichte und Küche, eignet es sich ideal für Städtereisen, Strandurlaub, Roadtrips und Genussreisen und ist von Deutschland aus gut erreichbar.$t$, $t$April bis Juni sowie September und Oktober für angenehme Temperaturen und Städtereisen; der Sommer eignet sich für Strände und Bergseen, ist in den Städten jedoch heiß und voll.$t$, $t$Städtereise 3 bis 4 Tage, Rundreise 1 bis 2 Wochen$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Strandurlaub$t$,$t$Kulinarik$t$,$t$Rundreise$t$,$t$Roadtrip$t$,$t$Familien$t$]::text[], $j${"currency":"Euro (EUR)","language":"Italienisch","flightTime":"ca. 1,5 bis 2 Stunden ab Deutschland (Rom, Mailand); der Norden ist auch mit dem Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Rom – Kolosseum, Forum Romanum, Vatikan und der Trevi-Brunnen","Venedig – Kanäle, Markusplatz und Gondelfahrten","Florenz und die Toskana – Renaissancekunst, Chianti und Zypressenhügel","Amalfiküste und Capri – dramatische Steilküste und mediterranes Flair","Mailand – Dom, Mode und Design","Garda- und Comer See – Bergseen mit malerischen Orten","Cinque Terre – fünf bunte Dörfer an der ligurischen Küste","Sizilien – der Ätna, antike Tempel und das elegante Taormina"]$j$::jsonb, $j$["In vielen Altstädten gelten verkehrsbeschränkte Zonen (ZTL); wer dort unerlaubt mit dem Auto einfährt, riskiert empfindliche Bußgelder – am besten außerhalb parken.","Tickets für stark besuchte Attraktionen wie den Vatikan, die Uffizien und das Kolosseum sollte man unbedingt vorab online buchen.","Einen Espresso trinkt man günstig im Stehen an der Bar; einen Cappuccino bestellen Italiener traditionell nur am Vormittag.","Für mildere Temperaturen und weniger Andrang lohnt sich die Nebensaison im Mai oder September statt des heißen Hochsommers."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Italien?","answer":"Für Städtereisen sind April bis Juni sowie September und Oktober ideal, da es dann angenehm warm und weniger überlaufen ist. Der Sommer eignet sich für Strände und Bergseen, in den Städten wird es dann jedoch sehr heiß und voll."},{"question":"Welche Währung gilt in Italien?","answer":"In Italien zahlt man mit dem Euro (EUR). Kartenzahlung ist verbreitet, etwas Bargeld empfiehlt sich für kleine Bars, Märkte und Trinkgeld."},{"question":"Brauche ich ein Visum für Italien?","answer":"Nein. Italien ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Lohnt sich ein Mietwagen in Italien?","answer":"Für Städte ist ein Auto wegen der ZTL-Zonen und des hervorragenden Zugnetzes oft hinderlich. Für Regionen wie die Toskana, Apulien oder Sizilien ist ein Mietwagen jedoch sehr empfehlenswert. An der Amalfiküste sind Bus oder Fähre meist entspannter."},{"question":"Was sind die ZTL-Zonen in Italien?","answer":"ZTL (Zona a Traffico Limitato) sind verkehrsbeschränkte Bereiche in vielen Altstädten, in die nur Berechtigte einfahren dürfen. Die Zufahrt wird oft per Kamera überwacht, unerlaubtes Einfahren führt zu Bußgeldern."},{"question":"Reist man in Italien gut mit dem Zug?","answer":"Ja, Italien verfügt über ein sehr gutes Netz an Hochgeschwindigkeitszügen, die Städte wie Rom, Florenz, Venedig und Mailand schnell verbinden. Tickets sind im Voraus oft günstiger."},{"question":"Ist Italien für einen Familienurlaub geeignet?","answer":"Ja, Italien ist sehr familienfreundlich. Es bietet Strände an Adria und Mittelmeer, Bergseen, kinderfreundliche Städte, Eis an jeder Ecke und eine herzliche Gastfreundschaft gegenüber Kindern."},{"question":"Welche Regionen in Italien sollte man besuchen?","answer":"Beliebt sind Rom und Latium, die Toskana, Venetien mit Venedig, die Amalfiküste und Kampanien, Sizilien sowie der Norden mit den Bergseen und Südtirol. Die Auswahl hängt von Interessen und Reisezeit ab."},{"question":"Welche Spezialitäten sollte man in Italien probieren?","answer":"Neben Pizza und Pasta lohnen sich regionale Spezialitäten wie Risotto im Norden, Bistecca alla Fiorentina in der Toskana, frische Meeresfrüchte im Süden sowie Espresso, Aperitivo und Gelato."},{"question":"Hat Italien schöne Strände?","answer":"Ja, von den Stränden der Adria über die Amalfiküste und Sardinien bis Sizilien bietet Italien eine große Vielfalt. Viele Strände sind als Lidos organisiert, an denen man Liegen und Schirme mieten kann."},{"question":"Wie viele Tage sollte man für Italien einplanen?","answer":"Für eine Stadt wie Rom, Florenz oder Venedig reichen 3 bis 4 Tage. Für eine Rundreise durch mehrere Regionen oder einen Roadtrip durch die Toskana sollte man 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Italien Urlaub: Rom, Toskana, Amalfiküste & beste Reisezeit$t$, $t$Dein Italien-Urlaub: Rom, Venedig, die Toskana, die Amalfiküste, Sizilien und die Bergseen. Beste Reisezeit, Highlights, Regionen und praktische Reisetipps im Überblick.$t$, $t$Italien Urlaub buchen, Flug und Hotel Rom oder Mailand, Ferienhaus Toskana, Mietwagen Italien vergleichen, Roadtrip Italien, Strandurlaub Adria oder Sardinien$t$, true, $j$["spanien","frankreich","griechenland"]$j$::jsonb, ARRAY[$t$Italien$t$,$t$Rom$t$,$t$Kolosseum$t$,$t$Vatikan$t$,$t$Venedig$t$,$t$Florenz$t$,$t$Toskana$t$,$t$Amalfiküste$t$,$t$Capri$t$,$t$Mailand$t$,$t$Gardasee$t$,$t$Comer See$t$,$t$Cinque Terre$t$,$t$Sizilien$t$,$t$Ätna$t$,$t$Dolomiten$t$]::text[], $t$Italien ist eines der beliebtesten Reiseländer der Welt und vereint Städte wie Rom, Venedig, Florenz und Mailand mit der Toskana, der Amalfiküste, Sizilien sowie den Bergseen und Dolomiten im Norden. Berühmt für Kunst, Geschichte und Küche, eignet es sich ideal für Städtereisen, Strandurlaub, Roadtrips und Genussreisen und ist von Deutschland aus gut erreichbar. Die beste Reisezeit liegt im Frühling und Frühherbst.$t$, $t$Italien ist ein vielseitiges Mittelmeerland mit Rom, Venedig, der Toskana, der Amalfiküste, Sizilien und weltberühmter Küche.$t$, $t$https://www.apearound.de/reiseziele/italien$t$, $t$/images/destinations/italien.jpg$t$, $t$/images/destinations/italien.jpg$t$, $t$Italien Urlaub: Rom, Toskana, Amalfiküste & beste Reisezeit$t$, $t$Dein Italien-Urlaub: Rom, Venedig, die Toskana, die Amalfiküste, Sizilien und die Bergseen. Beste Reisezeit, Highlights, Regionen und praktische Reisetipps im Überblick.$t$, $t$Italien Urlaub: Rom, Toskana, Amalfiküste & beste Reisezeit$t$, $t$Dein Italien-Urlaub: Rom, Venedig, die Toskana, die Amalfiküste, Sizilien und die Bergseen. Beste Reisezeit, Highlights, Regionen und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Jamaika
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Jamaika$t$, $t$jamaika$t$, $t$Jamaika$t$, $t$Karibik$t$, $t$Nordamerika$t$, $t$/images/destinations/jamaika-hero.jpg$t$, $t$Lebensfrohe Karibikinsel mit Traumstränden, Reggae und Bob-Marley-Erbe, Wasserfällen, den grünen Blue Mountains und entspanntem Inselflair.$t$, $t$Jamaika ist die Heimat des Reggae und steht wie kaum eine andere Karibikinsel für Lebensfreude, Rhythmus und entspanntes Inselgefühl. Türkisfarbenes Meer und Traumstrände wie der Seven Mile Beach in Negril oder der Doctor's Cave Beach in Montego Bay laden zum Baden ein, während komfortable All-Inclusive-Resorts in Ocho Rios, Negril und Montego Bay für sorglose Erholung sorgen. Naturhighlights wie die berühmten Dunn's River Falls, die man hinaufklettern kann, die leuchtende Luminous Lagoon und die grünen Blue Mountains mit ihrem weltbekannten Kaffee zeigen die landschaftliche Vielfalt der Insel. Kulturell ist Jamaika untrennbar mit Bob Marley und dem Reggae verbunden – sein Geburtsort Nine Mile und Kingston sind beliebte Pilgerstätten für Musikfans. Dazu kommen die würzige Jerk-Küche, herzliche Menschen und eine ansteckende Gelassenheit nach dem Motto „No Problem“. Jamaika ist ideal für Strandurlaub, Erholung, Flitterwochen und alle, die Karibik mit kulturellem Flair erleben möchten.$t$, $t$Jamaika ist eine lebensfrohe Karibikinsel mit Traumstränden, dem Erbe von Reggae und Bob Marley, Wasserfällen wie den Dunn's River Falls und den grünen Blue Mountains. Sie bietet komfortable All-Inclusive-Resorts und entspanntes Inselflair und eignet sich ideal für Strandurlaub, Erholung und Flitterwochen.$t$, $t$Die beste Reisezeit ist die Trockenzeit von November bis April; von Juni bis November ist Hurrikan-Saison mit höherem Sturmrisiko, besonders zwischen August und Oktober.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$All-Inclusive$t$,$t$Erholung$t$,$t$Kulturreise$t$,$t$Flitterwochen$t$,$t$Naturreise$t$,$t$Familien$t$]::text[], $j${"currency":"Jamaika-Dollar (JMD); in touristischen Gebieten wird oft auch der US-Dollar akzeptiert","language":"Englisch (Amtssprache); umgangssprachlich das jamaikanische Patois","flightTime":"ca. 11 Stunden ab Deutschland, meist mit Zwischenstopp (Montego Bay)","timezone":"EST (UTC−5), sechs Stunden hinter MEZ; keine Zeitumstellung","visa":"Kein Visum nötig für touristische Aufenthalte (bis 90 Tage); vor der Einreise ist das Online-Einreiseformular auszufüllen","bestMonths":"November bis April"}$j$::jsonb, $j$["Seven Mile Beach in Negril – langer Traumstrand mit Sonnenuntergängen","Dunn's River Falls bei Ocho Rios – berühmter Wasserfall zum Hinaufklettern","Blue Mountains – grüne Bergwelt und Heimat des weltbekannten Blue Mountain Coffee","Bob-Marley-Erbe – sein Geburtsort Nine Mile und das Bob-Marley-Museum in Kingston","Rick's Café in Negril – Klippenspringen und Sonnenuntergangsstimmung","Luminous Lagoon – nächtlich biolumineszent leuchtendes Wasser","Doctor's Cave Beach in Montego Bay – klares Wasser und Schnorcheln","Port Antonio und die Blue Lagoon – ruhigerer, ursprünglicher Inselosten"]$j$::jsonb, $j$["Jamaika ist die Wiege des Reggae – ein Besuch in Bob Marleys Geburtsort Nine Mile oder im Museum in Kingston lohnt sich für Musikfans besonders.","Unbedingt original jamaikanisches Jerk Chicken oder Jerk Pork probieren, am authentischsten an einfachen Ständen, etwa rund um Boston Bay.","Der US-Dollar wird vielerorts akzeptiert, das Wechselgeld erhält man jedoch meist in Jamaika-Dollar – kleine Beträge in Landeswährung sind praktisch.","Den Sonnenuntergang erlebt man stimmungsvoll im Rick's Café in Negril, wo Mutige von den Klippen ins Meer springen."]$j$::jsonb, $j$[{"question":"Kann man Jamaika 2026 nach Hurrikan Melissa wieder bereisen?","answer":"Ja. Nach dem Hurrikan im Oktober 2025 lief der Wiederaufbau zügig, und der Tourismussektor wurde im Laufe des Jahres 2026 wieder voll betriebsbereit. Regionen wie Negril, Ocho Rios, Port Antonio und Kingston waren ohnehin kaum betroffen. Vor der Buchung lohnt ein Blick auf den aktuellen Status der jeweiligen Region und Hotels."},{"question":"Wann ist die beste Reisezeit für Jamaika?","answer":"Ideal ist die Trockenzeit von November bis April mit viel Sonne und angenehmer Luftfeuchtigkeit. Von Juni bis November ist Hurrikan-Saison, mit dem höchsten Risiko zwischen August und Oktober."},{"question":"Brauche ich ein Visum für Jamaika?","answer":"Nein, für touristische Aufenthalte bis zu 90 Tagen benötigen deutsche Staatsbürger kein Visum. Vor der Einreise ist jedoch ein Online-Einreiseformular auszufüllen. Der Reisepass sollte für die Dauer des Aufenthalts gültig sein."},{"question":"Welche Währung gilt in Jamaika?","answer":"Offizielle Währung ist der Jamaika-Dollar (JMD). In Resorts und touristischen Gebieten wird häufig auch der US-Dollar akzeptiert. Für Trinkgelder und kleinere Ausgaben empfiehlt sich etwas Bargeld."},{"question":"Lohnt sich ein Mietwagen auf Jamaika?","answer":"Die meisten Urlauber bleiben im All-Inclusive-Resort und nutzen organisierte Ausflüge oder Transfers. Ein Mietwagen ist nicht nötig; wer dennoch fährt, sollte den Linksverkehr und den teils anspruchsvollen Straßenzustand beachten."},{"question":"Ist Jamaika sicher für Reisende?","answer":"Die Touristenregionen und Resorts gelten als gut bereisbar. Allerdings hat Jamaika in einigen Gebieten eine hohe Kriminalität, weshalb das Auswärtige Amt von nicht notwendigen Reisen in bestimmte Regionen abrät. Vor der Reise sollte man die aktuellen Reise- und Sicherheitshinweise prüfen und sich vorwiegend in den bekannten Resortgebieten bewegen."},{"question":"Kann man auf Jamaika das Leitungswasser trinken?","answer":"In Resorts und größeren Orten gilt das Leitungswasser meist als aufbereitet und trinkbar. Zur Sicherheit greifen viele Reisende dennoch auf abgefülltes Wasser zurück, besonders in ländlichen Gebieten."},{"question":"Welche Impfungen werden für Jamaika empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A. Für eine individuelle Beratung sollte man rechtzeitig den Hausarzt oder ein Tropeninstitut aufsuchen."},{"question":"Ist Jamaika für einen Familienurlaub geeignet?","answer":"Ja, viele Resorts sind familienfreundlich und bieten flache Strände, Pools und Animation. Ausflüge wie die Dunn's River Falls oder Bootstouren sorgen für zusätzliche Abwechslung für Kinder."},{"question":"Was sollte man kulinarisch auf Jamaika probieren?","answer":"Typisch sind Jerk Chicken und Jerk Pork, Ackee and Saltfish (das Nationalgericht), Curry-Gerichte, frischer Fisch sowie tropische Früchte. Dazu passen der Blue Mountain Coffee und der berühmte jamaikanische Rum."},{"question":"Eignet sich Jamaika für Flitterwochen?","answer":"Ja, mit romantischen Stränden, stimmungsvollen Sonnenuntergängen und Resorts speziell für Paare zählt Jamaika zu den beliebten Zielen für Flitterwochen und Hochzeitsreisen."},{"question":"Wie viel Zeit sollte man für Jamaika einplanen?","answer":"Für einen erholsamen Strandurlaub sind 1 bis 2 Wochen ideal. Wer zusätzlich Natur, Wasserfälle und das musikalische Erbe der Insel erleben möchte, profitiert von der längeren Variante mit mehreren Ausflügen."}]$j$::jsonb, $t$Jamaika Urlaub: Strände, Reggae, Reisetipps & beste Reisezeit$t$, $t$Dein Jamaika-Urlaub: Traumstrände wie der Seven Mile Beach, die Dunn's River Falls, das Reggae- und Bob-Marley-Erbe und die Blue Mountains. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Jamaika All-Inclusive buchen, Flug und Hotel Montego Bay, Pauschalreise Karibik, Strandurlaub Negril oder Ocho Rios, Flitterwochen Jamaika$t$, false, $j$["dominikanische-republik","kuba","mexiko"]$j$::jsonb, ARRAY[$t$Jamaika$t$,$t$Negril$t$,$t$Seven Mile Beach$t$,$t$Montego Bay$t$,$t$Ocho Rios$t$,$t$Dunn's River Falls$t$,$t$Blue Mountains$t$,$t$Bob Marley$t$,$t$Nine Mile$t$,$t$Kingston$t$,$t$Reggae$t$,$t$Rick's Café$t$,$t$Luminous Lagoon$t$,$t$Port Antonio$t$,$t$Jerk Chicken$t$,$t$Jamaika-Dollar$t$]::text[], $t$Jamaika ist eine lebensfrohe Karibikinsel und die Heimat des Reggae, bekannt für Traumstrände wie den Seven Mile Beach in Negril, die Dunn's River Falls, das Erbe von Bob Marley und die grünen Blue Mountains mit ihrem berühmten Kaffee. Die Insel bietet komfortable All-Inclusive-Resorts und entspanntes Inselflair und eignet sich ideal für Strandurlaub, Erholung und Flitterwochen. Die beste Reisezeit ist die Trockenzeit von November bis April.$t$, $t$Jamaika ist eine lebensfrohe Karibikinsel mit Traumstränden, Reggae- und Bob-Marley-Erbe, Wasserfällen und den Blue Mountains, am besten von November bis April.$t$, $t$https://www.apearound.de/reiseziele/jamaika$t$, $t$/images/destinations/jamaika.jpg$t$, $t$/images/destinations/jamaika.jpg$t$, $t$Jamaika Urlaub: Strände, Reggae, Reisetipps & beste Reisezeit$t$, $t$Dein Jamaika-Urlaub: Traumstrände wie der Seven Mile Beach, die Dunn's River Falls, das Reggae- und Bob-Marley-Erbe und die Blue Mountains. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Jamaika Urlaub: Strände, Reggae, Reisetipps & beste Reisezeit$t$, $t$Dein Jamaika-Urlaub: Traumstrände wie der Seven Mile Beach, die Dunn's River Falls, das Reggae- und Bob-Marley-Erbe und die Blue Mountains. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Japan
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Japan$t$, $t$japan$t$, $t$Japan$t$, $t$Ostasien$t$, $t$Asien$t$, $t$/images/destinations/japan-hero.jpg$t$, $t$Faszinierendes Land zwischen Tradition und Hightech mit Tokios Neonlichtern, Kyotos Tempeln, dem Fuji, Kirschblüte, Sushi und der Hochgeschwindigkeit der Shinkansen.$t$, $t$Japan verbindet wie kein anderes Land jahrhundertealte Tradition mit modernster Technologie und einer einzigartigen Ästhetik. Die Hauptstadt Tokio überwältigt mit Neonlichtern, der berühmten Kreuzung in Shibuya, den Vierteln Shinjuku und Akihabara sowie dem traditionellen Senso-ji-Tempel in Asakusa. Das kaiserliche Kyoto ist das kulturelle Herz mit zahllosen Tempeln, dem leuchtend roten Torii-Tunnel von Fushimi Inari, dem goldenen Pavillon Kinkaku-ji und dem Geisha-Viertel Gion. Über allem thront der heilige Vulkan Fuji. In Hiroshima erinnert der Friedenspark, während das vorgelagerte Miyajima mit seinem im Wasser stehenden Torii verzaubert. Nara begeistert mit freilaufenden Rehen und Osaka mit seiner legendären Streetfood-Szene. Die Kirschblüte im Frühling und das leuchtende Herbstlaub gehören zu den schönsten Naturschauspielen der Welt. Dank der pünktlichen Shinkansen-Hochgeschwindigkeitszüge reist man mühelos durchs Land. Japan ist ideal für Kultur-, Städte- und Kulinarikreisen – sicher, sauber und überaus gastfreundlich.$t$, $t$Japan ist ein faszinierendes Reiseland in Ostasien zwischen Tradition und Hightech mit Tokio, den Tempeln Kyotos, dem Fuji, der Kirschblüte, exzellenter Küche und den Shinkansen-Hochgeschwindigkeitszügen. Es ist visumfrei, sehr sicher und gut zu bereisen und eignet sich ideal für Kultur-, Städte- und Kulinarikreisen.$t$, $t$Frühling (März bis Mai) zur Kirschblüte und Herbst (Oktober bis November) zur Laubfärbung sind ideal; der Sommer ist heiß und schwül, der Winter eignet sich für Wintersport und heiße Quellen.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Kulturreise$t$,$t$Städtereise$t$,$t$Kulinarik$t$,$t$Naturreise$t$,$t$Abenteuer$t$]::text[], $j${"currency":"Japanischer Yen (JPY)","language":"Japanisch","flightTime":"ca. 11 bis 12 Stunden ab Deutschland im Direktflug (Tokio)","timezone":"JST (UTC+9), acht Stunden vor MEZ","visa":"Kein Visum nötig für touristische Aufenthalte bis 90 Tage","bestMonths":"März bis Mai sowie Oktober und November"}$j$::jsonb, $j$["Tokio – Shibuya-Kreuzung, Shinjuku, Akihabara und der Senso-ji-Tempel","Kyoto – Tempel, Fushimi Inari, der goldene Pavillon Kinkaku-ji und das Geisha-Viertel Gion","Berg Fuji – der heilige Vulkan und das Wahrzeichen Japans","Hiroshima und Miyajima – Friedenspark und das im Wasser stehende Torii","Nara – Tempel und freilaufende Rehe im Park","Osaka – legendäre Streetfood-Szene rund um Dotonbori","Kirschblüte und Herbstlaub – spektakuläre Naturschauspiele","Shinkansen – die pünktlichen Hochgeschwindigkeitszüge"]$j$::jsonb, $j$["Für längere Bahnstrecken kann sich der Japan Rail Pass lohnen; für den Nahverkehr nutzt man eine aufladbare IC-Karte wie Suica oder Pasmo.","Wer die Kirschblüte (Sakura) erleben möchte, reist meist Ende März bis April; die Laubfärbung im Herbst ist im November am schönsten – beide Zeiten sind beliebt und sollten früh gebucht werden.","In Japan gibt es kein Trinkgeld, und auf Etikette wird Wert gelegt: in vielen Innenräumen Schuhe ausziehen, in Zügen leise sein und Müll oft selbst mitnehmen.","Die Convenience Stores (Konbini) bieten überraschend gutes und günstiges Essen rund um die Uhr und sind ideale Anlaufstellen für unterwegs."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Japan?","answer":"Nein, deutsche Staatsbürger benötigen für touristische Aufenthalte bis zu 90 Tagen kein Visum. Der Reisepass sollte für die Dauer des Aufenthalts gültig sein."},{"question":"Wann ist die beste Reisezeit für Japan?","answer":"Am schönsten sind das Frühjahr mit der Kirschblüte (Ende März bis April) und der Herbst mit der Laubfärbung (Oktober bis November). Der Sommer ist heiß und schwül, der Winter bietet Wintersport und stimmungsvolle heiße Quellen."},{"question":"Welche Währung gilt in Japan?","answer":"Gezahlt wird mit dem Japanischen Yen (JPY). Kartenzahlung ist in Städten verbreitet, dennoch ist Bargeld weiterhin wichtig, besonders in kleineren Lokalen, Tempeln und auf dem Land. Geld hebt man gut an Automaten in Convenience Stores ab."},{"question":"Wie reist man am besten innerhalb Japans?","answer":"Das hervorragende Zugnetz mit den Shinkansen-Hochgeschwindigkeitszügen ist das beste Verkehrsmittel zwischen den Städten. In den Metropolen nutzt man Metro und Nahverkehr mit einer IC-Karte. Ein eigener Mietwagen ist meist nicht nötig."},{"question":"Lohnt sich der Japan Rail Pass?","answer":"Das hängt von der Route ab. Wer längere Strecken wie Tokio–Kyoto–Hiroshima fährt, kann mit dem Japan Rail Pass sparen. Für kürzere oder regionale Reisen sind Einzeltickets oder regionale Pässe oft günstiger – am besten vorab durchrechnen."},{"question":"Spricht man in Japan Englisch?","answer":"In großen Städten und an touristischen Orten kommt man mit Englisch meist zurecht, und vieles ist beschildert. Abseits davon sind die Kenntnisse begrenzt; eine Übersetzungs-App und etwas Geduld helfen weiter."},{"question":"Ist Japan ein teures Reiseland?","answer":"Japan ist nicht so teuer wie sein Ruf. Unterkünfte und Bahnfahrten können kosten, doch Essen ist oft erschwinglich – etwa in Ramen-Läden, Konbini oder Standlokalen. Mit guter Planung lässt sich Japan gut budgetieren."},{"question":"Was sollte man bei der Etikette beachten?","answer":"Trinkgeld ist unüblich und kann sogar als unhöflich gelten. In vielen Innenräumen zieht man die Schuhe aus, in Zügen verhält man sich leise, und beim Essen sowie in Tempeln gelten bestimmte Höflichkeitsregeln."},{"question":"Ist Japan für einen Familienurlaub geeignet?","answer":"Ja, Japan ist sehr sicher, sauber und familienfreundlich. Themenparks, Tierbegegnungen wie die Rehe in Nara, moderne Städte und kindgerechtes Essen begeistern Familien. Die gute Infrastruktur macht das Reisen unkompliziert."},{"question":"Was hat es mit den Onsen auf sich?","answer":"Onsen sind heiße Quellenbäder und ein fester Bestandteil der japanischen Kultur. Vor dem Baden wäscht man sich gründlich, gebadet wird ohne Badekleidung. In manchen Onsen sind Tätowierungen eingeschränkt; im Zweifel vorher nachfragen."},{"question":"Wie viele Tage sollte man für Japan einplanen?","answer":"Für die klassische Route Tokio–Kyoto–Osaka reichen etwa 10 bis 14 Tage. Wer zusätzlich Hiroshima, den Norden oder den Süden erleben möchte, sollte 2 bis 3 Wochen einplanen."}]$j$::jsonb, $t$Japan Urlaub: Tokio, Kyoto, Kirschblüte & beste Reisezeit$t$, $t$Dein Japan-Urlaub: Tokio, die Tempel Kyotos, der Berg Fuji, die Kirschblüte und die Shinkansen-Züge. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Japan Rundreise buchen, Flug nach Tokio, Hotel Tokio oder Kyoto, Japan Rail Pass, Kirschblüte Reise Japan, Rundreise Japan$t$, false, $j$["china","suedkorea","vietnam"]$j$::jsonb, ARRAY[$t$Japan$t$,$t$Tokio$t$,$t$Shibuya$t$,$t$Senso-ji$t$,$t$Kyoto$t$,$t$Fushimi Inari$t$,$t$Kinkaku-ji$t$,$t$Gion$t$,$t$Berg Fuji$t$,$t$Hiroshima$t$,$t$Miyajima$t$,$t$Nara$t$,$t$Osaka$t$,$t$Kirschblüte$t$,$t$Shinkansen$t$,$t$Japanischer Yen$t$]::text[], $t$Japan ist ein faszinierendes Reiseland in Ostasien zwischen Tradition und Hightech mit der Metropole Tokio, den Tempeln des kaiserlichen Kyoto, dem heiligen Berg Fuji, der berühmten Kirschblüte, exzellenter Küche und den pünktlichen Shinkansen-Hochgeschwindigkeitszügen. Das Land ist visumfrei, sehr sicher und sauber und eignet sich ideal für Kultur-, Städte- und Kulinarikreisen. Die beste Reisezeit ist das Frühjahr zur Kirschblüte und der Herbst zur Laubfärbung.$t$, $t$Japan ist ein Land zwischen Tradition und Hightech mit Tokio, den Tempeln Kyotos, dem Fuji, der Kirschblüte und den Shinkansen-Zügen, visumfrei bereisbar.$t$, $t$https://www.apearound.de/reiseziele/japan$t$, $t$/images/destinations/japan.jpg$t$, $t$/images/destinations/japan.jpg$t$, $t$Japan Urlaub: Tokio, Kyoto, Kirschblüte & beste Reisezeit$t$, $t$Dein Japan-Urlaub: Tokio, die Tempel Kyotos, der Berg Fuji, die Kirschblüte und die Shinkansen-Züge. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Japan Urlaub: Tokio, Kyoto, Kirschblüte & beste Reisezeit$t$, $t$Dein Japan-Urlaub: Tokio, die Tempel Kyotos, der Berg Fuji, die Kirschblüte und die Shinkansen-Züge. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
