-- Kambodscha
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Kambodscha$t$, $t$kambodscha$t$, $t$Kambodscha$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/kambodscha-hero.jpg$t$, $t$Faszinierendes Südostasien-Ziel mit den weltberühmten Angkor-Tempeln, bewegender Geschichte, dem Tonle-Sap-See und einsamen Inselstränden.$t$, $t$Kambodscha vereint eine der großartigsten Tempelanlagen der Welt mit bewegender Geschichte, herzlichen Menschen und ursprünglicher Natur. Das unangefochtene Highlight ist die gewaltige Tempelstadt Angkor bei Siem Reap mit dem ikonischen Angkor Wat, den geheimnisvollen Gesichtertürmen des Bayon und dem von Wurzeln überwucherten Ta Prohm. In der Hauptstadt Phnom Penh treffen der prächtige Königspalast und lebendige Märkte auf die erschütternden Erinnerungsorte der Roten Khmer, etwa die Killing Fields und das Gefängnis Tuol Sleng. Am riesigen Tonle-Sap-See lässt sich das Leben in schwimmenden Dörfern erleben, während der ländliche Charme rund um Battambang und das gemächliche Kampot mit seinen Pfefferplantagen zum Verweilen einladen. Im Süden warten Strände und einsame Inseln wie Koh Rong. Kambodscha ist günstig, weniger überlaufen als seine Nachbarn und ideal für Reisende, die Kultur, Geschichte und Natur verbinden möchten.$t$, $t$Kambodscha ist ein faszinierendes Reiseland in Südostasien mit der weltberühmten Tempelstadt Angkor bei Siem Reap, der geschichtsträchtigen Hauptstadt Phnom Penh, dem Tonle-Sap-See und einsamen Inselstränden im Süden. Es ist günstig, gastfreundlich und eignet sich ideal für Kultur-, Geschichts- und Rundreisen.$t$, $t$Die beste Reisezeit ist die kühle Trockenzeit von November bis Februar; insgesamt sind November bis März günstig, während von Mai bis Oktober Regenzeit herrscht.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Kulturreise$t$,$t$Geschichtsreise$t$,$t$Strandurlaub$t$,$t$Backpacking$t$,$t$Abenteuer$t$]::text[], $j${"currency":"Kambodschanischer Riel (KHR); der US-Dollar ist als Zweitwährung weit verbreitet","language":"Khmer","flightTime":"Keine Direktflüge; ca. 14 bis 15 Stunden mit Zwischenstopp (Phnom Penh, Siem Reap)","timezone":"ICT (UTC+7), sechs Stunden vor MEZ","visa":"Visum erforderlich; als E-Visum vorab oder als Visa on Arrival (in der Regel 30 Tage) erhältlich","bestMonths":"November bis Februar"}$j$::jsonb, $j$["Angkor Wat – größtes religiöses Bauwerk der Welt und Wahrzeichen Kambodschas","Bayon – Tempel mit den berühmten steinernen Gesichtertürmen","Ta Prohm – von mächtigen Baumwurzeln überwucherter Dschungeltempel","Phnom Penh – Königspalast, Märkte und Erinnerungsorte der Roten Khmer","Tonle-Sap-See – schwimmende Dörfer und einzigartiges Leben auf dem Wasser","Koh Rong und Koh Rong Sanloem – Inseln mit weißen Stränden im Süden","Battambang – ländlicher Charme, Tempel und der Bamboo Train","Kampot und Kep – Pfefferplantagen, Flusslandschaft und Küstenflair"]$j$::jsonb, $j$["Den Sonnenaufgang über Angkor Wat sollte man früh ansteuern – das Farbenspiel über den Tempeltürmen ist trotz der Menschenmengen ein unvergessliches Erlebnis.","Mit einem Mehrtagespass für Angkor lohnt es sich, auch abgelegenere Tempel jenseits der Hauptanlagen zu erkunden, wo es deutlich ruhiger ist.","Der US-Dollar wird fast überall akzeptiert; das Wechselgeld unter einem Dollar erhält man jedoch in Riel – kleine Scheine sind praktisch.","Die Besuche der Killing Fields und des Tuol-Sleng-Museums sind bedrückend, aber wichtig, um die jüngere Geschichte Kambodschas zu verstehen."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Kambodscha?","answer":"Ja, deutsche Staatsbürger benötigen ein Visum. Es ist bequem als E-Visum vorab online oder als Visa on Arrival bei der Einreise erhältlich und gilt in der Regel für 30 Tage. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Kambodscha?","answer":"Ideal ist die kühle Trockenzeit von November bis Februar. Insgesamt sind die Monate November bis März günstig, während von Mai bis Oktober Regenzeit mit hoher Luftfeuchtigkeit und Schauern herrscht."},{"question":"Welche Währung gilt in Kambodscha?","answer":"Offizielle Währung ist der Kambodschanische Riel (KHR), doch der US-Dollar ist als faktische Zweitwährung weit verbreitet und wird fast überall akzeptiert. Wechselgeld unter einem Dollar erhält man meist in Riel. Bargeld ist wichtig."},{"question":"Wie kommt man nach Kambodscha?","answer":"Es gibt keine Direktflüge aus Deutschland; die Anreise erfolgt mit Zwischenstopp, etwa über Bangkok, Singapur oder Doha. Beliebt ist auch die Kombination mit Vietnam oder Thailand und die Einreise auf dem Landweg."},{"question":"Wie reist man innerhalb Kambodschas?","answer":"Üblich sind Busse, Minivans, Inlandsflüge sowie Tuk-Tuks und Fahrzeuge mit Fahrer für Ausflüge. Ein eigener Mietwagen ist unüblich; für Tempeltouren in Angkor bietet sich ein Tuk-Tuk mit Fahrer für den Tag an."},{"question":"Wie viel Zeit sollte man für die Angkor-Tempel einplanen?","answer":"Für die wichtigsten Tempel reicht ein voller Tag, für ein entspannteres Erlebnis mit weiteren Anlagen empfehlen sich zwei bis drei Tage. Dafür gibt es entsprechende Mehrtagespässe."},{"question":"Ist Kambodscha sicher für Reisende?","answer":"Ja, Kambodscha gilt als sicheres Reiseland mit gastfreundlichen Menschen. Aufpassen sollte man auf Taschendiebstahl in Städten und im Straßenverkehr. In abgelegenen Gebieten gibt es noch Minenreste, weshalb man markierte Wege nicht verlassen sollte."},{"question":"Kann man in Kambodscha das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln sowie rohen Speisen vorsichtig sein."},{"question":"Welche Impfungen werden für Kambodscha empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Hat Kambodscha auch Strände?","answer":"Ja, im Süden rund um Sihanoukville und vor allem auf den Inseln Koh Rong und Koh Rong Sanloem gibt es schöne, teils noch ruhige Strände mit weißem Sand und klarem Wasser."},{"question":"Wie viele Tage sollte man für Kambodscha einplanen?","answer":"Für die Höhepunkte Angkor und Phnom Penh reicht etwa eine Woche. Wer zusätzlich den Süden mit den Inseln oder Battambang und Kampot erleben möchte, sollte rund 2 Wochen einplanen."}]$j$::jsonb, $t$Kambodscha Urlaub: Angkor Wat, Reisetipps & beste Reisezeit$t$, $t$Dein Kambodscha-Urlaub: die Tempel von Angkor Wat, Phnom Penh, der Tonle-Sap-See und Inselstrände wie Koh Rong. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Kambodscha Rundreise buchen, Flug nach Siem Reap oder Phnom Penh, Hotel Siem Reap, Angkor Wat Tour, Backpacking Südostasien, Kambodscha Vietnam Kombireise$t$, false, $j$["vietnam","thailand","laos"]$j$::jsonb, ARRAY[$t$Kambodscha$t$,$t$Angkor Wat$t$,$t$Angkor$t$,$t$Bayon$t$,$t$Ta Prohm$t$,$t$Siem Reap$t$,$t$Phnom Penh$t$,$t$Königspalast$t$,$t$Killing Fields$t$,$t$Tuol Sleng$t$,$t$Tonle-Sap-See$t$,$t$Koh Rong$t$,$t$Battambang$t$,$t$Kampot$t$,$t$Khmer$t$,$t$Kambodschanischer Riel$t$]::text[], $t$Kambodscha ist ein faszinierendes Reiseland in Südostasien, bekannt vor allem für die weltberühmte Tempelstadt Angkor mit Angkor Wat bei Siem Reap, die geschichtsträchtige Hauptstadt Phnom Penh, den Tonle-Sap-See und einsame Inselstrände wie Koh Rong im Süden. Das Land ist günstig, gastfreundlich und weniger überlaufen als seine Nachbarn und eignet sich ideal für Kultur-, Geschichts- und Rundreisen. Die beste Reisezeit ist die kühle Trockenzeit von November bis Februar.$t$, $t$Kambodscha ist ein Südostasien-Ziel mit den weltberühmten Angkor-Tempeln, der Hauptstadt Phnom Penh und Inselstränden, am besten von November bis Februar.$t$, $t$https://www.apearound.de/reiseziele/kambodscha$t$, $t$/images/destinations/kambodscha.jpg$t$, $t$/images/destinations/kambodscha.jpg$t$, $t$Kambodscha Urlaub: Angkor Wat, Reisetipps & beste Reisezeit$t$, $t$Dein Kambodscha-Urlaub: die Tempel von Angkor Wat, Phnom Penh, der Tonle-Sap-See und Inselstrände wie Koh Rong. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$Kambodscha Urlaub: Angkor Wat, Reisetipps & beste Reisezeit$t$, $t$Dein Kambodscha-Urlaub: die Tempel von Angkor Wat, Phnom Penh, der Tonle-Sap-See und Inselstrände wie Koh Rong. Beste Reisezeit, Visum, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Kanada
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Kanada$t$, $t$kanada$t$, $t$Kanada$t$, $t$Nordamerika$t$, $t$Nordamerika$t$, $t$/images/destinations/kanada-hero.jpg$t$, $t$Riesiges Naturparadies mit den Rocky Mountains, türkisen Bergseen, endlosen Wäldern, Niagarafällen, Bären, Walen und weltoffenen Metropolen.$t$, $t$Kanada ist das zweitgrößte Land der Erde und ein Sehnsuchtsziel für Naturliebhaber und Abenteurer. Das Highlight sind die Rocky Mountains mit den Nationalparks Banff und Jasper, wo türkisblaue Bergseen wie der Lake Louise und der Moraine Lake, schroffe Gipfel und Gletscher eine traumhafte Kulisse bilden – verbunden durch den Icefields Parkway, eine der schönsten Panoramastraßen der Welt. Im Westen begeistert das weltoffene Vancouver mit Vancouver Island, im Osten die imposanten Niagarafälle, das pulsierende Toronto sowie das französisch geprägte Montréal und Québec City. Im Herbst taucht der „Indian Summer“ die Wälder Ostkanadas in leuchtendes Rot und Gold. Tierbegegnungen mit Bären, Elchen und Walen gehören zu den unvergesslichen Erlebnissen, und im hohen Norden, etwa im Yukon, tanzen die Nordlichter. Wegen der enormen Distanzen sind Roadtrips und Wohnmobilreisen besonders beliebt. Kanada ist ideal für Natur-, Rundreise- und Outdoor-Urlaube und bekannt für seine herzliche, weltoffene Art.$t$, $t$Kanada ist ein riesiges Naturparadies mit den Rocky Mountains, türkisen Bergseen, Nationalparks wie Banff und Jasper, den Niagarafällen, reicher Tierwelt und weltoffenen Städten wie Vancouver, Toronto und Montréal. Es eignet sich ideal für Roadtrips, Wohnmobil- und Naturreisen; für Flugreisen ist eine eTA erforderlich.$t$, $t$Juni bis September für die Rocky Mountains, Roadtrips und Tierbeobachtung; September und Oktober für den „Indian Summer“ in Ostkanada; der Winter eignet sich für Wintersport und Nordlichter.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Roadtrip$t$,$t$Naturreise$t$,$t$Nationalparks$t$,$t$Abenteuer$t$,$t$Wandern$t$,$t$Wohnmobilreise$t$]::text[], $j${"currency":"Kanadischer Dollar (CAD)","language":"Englisch und Französisch (zwei Amtssprachen)","flightTime":"ca. 8,5 Stunden nach Toronto, rund 10 Stunden nach Vancouver ab Deutschland","timezone":"Mehrere Zeitzonen (Osten UTC−5 bis Pazifikküste UTC−8)","visa":"Kein Visum für Touristen (bis 6 Monate); für Flugreisen ist eine eTA (Electronic Travel Authorization, rund 7 CAD, 5 Jahre gültig) erforderlich","bestMonths":"Juni bis September; Indian Summer September bis Oktober"}$j$::jsonb, $j$["Rocky Mountains – Banff und Jasper mit Lake Louise und Moraine Lake","Icefields Parkway – eine der schönsten Panoramastraßen der Welt","Niagarafälle – gewaltige Wasserfälle an der Grenze zu den USA","Vancouver und Vancouver Island – Metropole, Natur und Wale","Toronto – pulsierende Metropole mit dem CN Tower","Montréal und Québec City – französisches Flair und Altstadtcharme","Indian Summer – leuchtende Herbstfärbung der Wälder Ostkanadas","Yukon und der Norden – Wildnis und Nordlichter"]$j$::jsonb, $j$["Der Icefields Parkway zwischen Banff und Jasper gehört zu den spektakulärsten Strecken der Welt – planen Sie viel Zeit für Stopps an Seen und Gletschern ein.","Eine Wohnmobilreise (Camper) ist in Kanada besonders beliebt und ideal, um die weiten Landschaften flexibel und naturnah zu erleben.","Für die Herbstfärbung des Indian Summer reist man Ende September bis Oktober in den Osten, etwa nach Québec oder in den Algonquin Park.","Tierbegegnungen mit Bären, Elchen und Walen sind möglich – stets respektvollen Abstand halten und in Bärengebieten die Hinweise zur Lebensmittelaufbewahrung beachten."]$j$::jsonb, $j$[{"question":"Brauche ich für Kanada ein Visum?","answer":"Für touristische Aufenthalte bis zu sechs Monaten benötigen deutsche Staatsbürger kein Visum. Für die Einreise auf dem Luftweg ist jedoch eine elektronische Reisegenehmigung (eTA) erforderlich, die vor dem Flug online beantragt wird."},{"question":"Was ist die eTA und was kostet sie?","answer":"Die eTA (Electronic Travel Authorization) ist eine elektronische Einreisegenehmigung für Flugreisen nach Kanada. Sie kostet rund 7 kanadische Dollar, ist nach Genehmigung bis zu fünf Jahre gültig und sollte rechtzeitig vor Abflug beantragt werden."},{"question":"Wann ist die beste Reisezeit für Kanada?","answer":"Für die Rocky Mountains, Roadtrips und Tierbeobachtung eignen sich Juni bis September. Für die leuchtende Herbstfärbung des Indian Summer reist man im September und Oktober in den Osten. Der Winter ist ideal für Wintersport und Nordlichter."},{"question":"Welche Währung gilt in Kanada?","answer":"Gezahlt wird mit dem Kanadischen Dollar (CAD). Kartenzahlung ist nahezu überall üblich. Wie in den USA werden Preise oft ohne Steuer ausgezeichnet, die erst an der Kasse hinzukommt, und Trinkgeld ist üblich."},{"question":"Lohnt sich ein Mietwagen oder Wohnmobil in Kanada?","answer":"Ja, wegen der riesigen Distanzen ist ein Mietwagen oder Wohnmobil fast unverzichtbar, besonders für Roadtrips durch die Rocky Mountains. Nur in den Großstädten ist ein Auto nicht zwingend nötig."},{"question":"Kann man in Kanada wild lebende Tiere beobachten?","answer":"Ja, Kanada ist berühmt für seine Tierwelt. Mit etwas Glück sieht man Bären, Elche, Biber und Adler; vor der Küste British Columbias lassen sich zudem Wale beobachten. Stets Abstand halten und Tiere nicht füttern."},{"question":"Wo sieht man in Kanada Nordlichter?","answer":"Die besten Chancen auf Polarlichter hat man im Norden, etwa im Yukon oder in den Nordwest-Territorien rund um Yellowknife, in dunklen, klaren Nächten von Spätsommer bis Frühjahr."},{"question":"Spricht man in Kanada Englisch oder Französisch?","answer":"Kanada ist offiziell zweisprachig. Englisch dominiert im größten Teil des Landes, während in der Provinz Québec, etwa in Montréal und Québec City, Französisch vorherrscht. Mit Englisch kommt man fast überall gut zurecht."},{"question":"Ist Kanada für einen Familienurlaub geeignet?","answer":"Ja, Kanada ist familienfreundlich und sehr sicher. Nationalparks, Tierbeobachtungen, Seen, einfache Wanderungen und weltoffene Städte bieten viel Abwechslung. Wegen der Distanzen sollte man die Route entspannt planen."},{"question":"Wie überbrückt man die großen Entfernungen in Kanada?","answer":"Für lange Strecken zwischen Ost und West sind Inlandsflüge das schnellste Mittel. Innerhalb einer Region erkundet man das Land am besten per Mietwagen oder Wohnmobil, da die öffentlichen Verbindungen begrenzt sind."},{"question":"Wie viele Tage sollte man für Kanada einplanen?","answer":"Für eine Region wie die Rocky Mountains oder den Osten rund um Toronto, Montréal und Québec sollte man etwa 2 Wochen einplanen. Wer mehrere Regionen verbinden möchte, plant wegen der Distanzen 3 Wochen oder mehr."}]$j$::jsonb, $t$Kanada Urlaub: Rocky Mountains, Roadtrip & beste Reisezeit$t$, $t$Dein Kanada-Urlaub: die Rocky Mountains mit Banff und Jasper, die Niagarafälle, Vancouver, der Indian Summer und reiche Tierwelt. Beste Reisezeit, eTA-Einreise, Highlights und Reisetipps im Überblick.$t$, $t$Kanada Reise buchen, Flug nach Toronto oder Vancouver, Mietwagen oder Wohnmobil Kanada, Rundreise Rocky Mountains, Roadtrip Westkanada, Hotel Vancouver$t$, true, $j$["amerika","norwegen","neuseeland"]$j$::jsonb, ARRAY[$t$Kanada$t$,$t$Rocky Mountains$t$,$t$Banff$t$,$t$Jasper$t$,$t$Lake Louise$t$,$t$Moraine Lake$t$,$t$Icefields Parkway$t$,$t$Niagarafälle$t$,$t$Vancouver$t$,$t$Vancouver Island$t$,$t$Toronto$t$,$t$CN Tower$t$,$t$Montréal$t$,$t$Québec City$t$,$t$Yukon$t$,$t$Kanadischer Dollar$t$]::text[], $t$Kanada ist das zweitgrößte Land der Erde und ein riesiges Naturparadies mit den Rocky Mountains, türkisen Bergseen, Nationalparks wie Banff und Jasper, den Niagarafällen, reicher Tierwelt und weltoffenen Städten wie Vancouver, Toronto und Montréal. Wegen der enormen Distanzen sind Roadtrips und Wohnmobilreisen besonders beliebt, und das Land eignet sich ideal für Natur-, Rundreise- und Outdoor-Urlaube. Für Flugreisen benötigen deutsche Reisende eine eTA, die beste Reisezeit liegt zwischen Juni und Oktober.$t$, $t$Kanada ist ein riesiges Naturparadies mit den Rocky Mountains, türkisen Bergseen, den Niagarafällen und reicher Tierwelt; für Flüge braucht man eine eTA.$t$, $t$https://www.apearound.de/reiseziele/kanada$t$, $t$/images/destinations/kanada.jpg$t$, $t$/images/destinations/kanada.jpg$t$, $t$Kanada Urlaub: Rocky Mountains, Roadtrip & beste Reisezeit$t$, $t$Dein Kanada-Urlaub: die Rocky Mountains mit Banff und Jasper, die Niagarafälle, Vancouver, der Indian Summer und reiche Tierwelt. Beste Reisezeit, eTA-Einreise, Highlights und Reisetipps im Überblick.$t$, $t$Kanada Urlaub: Rocky Mountains, Roadtrip & beste Reisezeit$t$, $t$Dein Kanada-Urlaub: die Rocky Mountains mit Banff und Jasper, die Niagarafälle, Vancouver, der Indian Summer und reiche Tierwelt. Beste Reisezeit, eTA-Einreise, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
